"use strict";(self.webpackChunkenterprise_ai_agents_applied_ml_book=self.webpackChunkenterprise_ai_agents_applied_ml_book||[]).push([[5285],{7565(e,t,n){n.r(t),n.d(t,{assets:()=>h,contentTitle:()=>l,default:()=>p,frontMatter:()=>d,metadata:()=>r,toc:()=>c});const r=JSON.parse('{"id":"part5-deep-learning-and-llms/recurrent-neural-networks","title":"Recurrent Neural Networks (RNNs) \u2014 Sequence Memory, GRU/LSTM, Translation, and Weight Sharing","description":"A practical, code-oriented tutorial on why RNNs exist, what goes in and comes out at each time step, how a basic Elman unit computes hidden state, how GRU/LSTM gates improve memory, and how recurrent weight sharing ke...","source":"@site/docs/part5-deep-learning-and-llms/10-recurrent-neural-networks.mdx","sourceDirName":"part5-deep-learning-and-llms","slug":"/part5-deep-learning-and-llms/10-recurrent-neural-networks","permalink":"/tutorials/part5-deep-learning-and-llms/10-recurrent-neural-networks","draft":false,"unlisted":false,"tags":[],"version":"current","lastUpdatedAt":1785375762000,"sidebarPosition":10,"frontMatter":{"title":"Recurrent Neural Networks (RNNs) \u2014 Sequence Memory, GRU/LSTM, Translation, and Weight Sharing","slug":"/part5-deep-learning-and-llms/10-recurrent-neural-networks","description":"A practical, code-oriented tutorial on why RNNs exist, what goes in and comes out at each time step, how a basic Elman unit computes hidden state, how GRU/LSTM gates improve memory, and how recurrent weight sharing ke...","sidebar_label":"10. Recurrent neural networks","pagination_label":"10. Recurrent neural networks","hide_title":true,"hide_table_of_contents":true},"sidebar":"bookSidebar","previous":{"title":"9. Autoregressive linear model","permalink":"/tutorials/part5-deep-learning-and-llms/09-autoregressive-linear-model"},"next":{"title":"11. Transformers and attention","permalink":"/tutorials/part5-deep-learning-and-llms/11-transformers-and-attention"}}');var a=n(4848),s=n(8453),o=n(8172);const i=JSON.parse('{"sourcePath":"part5-deep-learning-and-llms/10-recurrent-neural-networks.html","route":"/part5-deep-learning-and-llms/10-recurrent-neural-networks","kind":"chapter","partId":"part5","partLabel":"Part V - Deep Learning & Large Language Models","accent":"coral","heading":"Recurrent Neural Networks (RNNs): from sequence memory to GRU/LSTM and translation","title":"Recurrent Neural Networks (RNNs) \u2014 Sequence Memory, GRU/LSTM, Translation, and Weight Sharing","description":"A practical, code-oriented tutorial on why RNNs exist, what goes in and comes out at each time step, how a basic Elman unit computes hidden state, how GRU/LSTM gates improve memory, and how recurrent weight sharing ke...","readingMinutes":22,"bodyClass":"","normalizeMath":false,"toc":[{"id":"1-why-not-just-flatten-sequence-data-into-a-giant-vector","label":"1) Why not just flatten sequence data into a giant vector?"},{"id":"2-the-simplest-rnn-unit-elman-unit-equations-and-intuition","label":"2) The simplest RNN unit (Elman unit): equations and intuition"},{"id":"3-many-to-one-vs-many-to-many-why-you-might-ignore-most-outputs","label":"3) Many-to-one vs many-to-many: why you might \u201cignore\u201d most outputs"},{"id":"4-practical-seq2seq-example-translating-my-name-is-dinesh","label":"4) Practical seq2seq example: translating \u201cmy name is dinesh\u201d"},{"id":"5-pseudocode-forward-pass-through-a-sequence","label":"5) Pseudocode: forward pass through a sequence"},{"id":"6-cost-savings-rnn-vs-flattened-ann","label":"6) Cost savings: RNN vs flattened ANN"},{"id":"7-coding-it-in-pytorch-manual-loop-to-really-see-weight-sharing","label":"7) Coding it in PyTorch: manual loop (to really see weight sharing)"},{"id":"8-using-pytorch-s-built-in-nn-rnn-recommended-for-real-projects","label":"8) Using PyTorch\u2019s built-in nn.RNN (recommended for real projects)"},{"id":"9-why-vanilla-rnn-memory-breaks-overwriting-and-gradient-chains","label":"9) Why vanilla RNN memory breaks: overwriting and gradient chains"},{"id":"10-gates-learnable-valves-for-memory","label":"10) Gates: learnable valves for memory"},{"id":"11-gru-the-simpler-gated-memory-cell","label":"11) GRU: the simpler gated memory cell"},{"id":"12-lstm-separate-long-term-memory-from-exposed-hidden-state","label":"12) LSTM: separate long-term memory from exposed hidden state"},{"id":"13-gru-vs-lstm-vs-vanilla-rnn-when-to-use-which","label":"13) GRU vs LSTM vs vanilla RNN: when to use which"},{"id":"14-why-attention-still-mattered-after-gru-lstm","label":"14) Why attention still mattered after GRU/LSTM"},{"id":"15-quick-mental-model-recap","label":"15) Quick mental model recap"}],"html":"<main class=\\"wrap\\">\\n    <span class=\\"badge\\">Sequence models</span>\\n    \\n    <p class=\\"subtitle\\">\\n      A practical, code-oriented tutorial on <em>why</em> RNNs exist, <em>what goes in and comes out</em> at each time step,\\n      how a basic Elman unit computes hidden state, how GRU/LSTM gates improve memory, and how recurrent weight sharing\\n      keeps sequence models compact.\\n    </p>\\n\\n    <div class=\\"callout\\">\\n      <strong>Big idea:</strong> An RNN processes a sequence by applying the <em>same</em> small neural \u201ccell\u201d at every time step.\\n      The cell carries a <em>hidden state</em> forward, so the output at time \\\\(t\\\\) can depend on both the current input \\\\(x_t\\\\)\\n      and the memory of earlier inputs \\\\(h_{t-1}\\\\).\\n    </div>\\n\\n    <h2 id=\\"1-why-not-just-flatten-sequence-data-into-a-giant-vector\\">1) Why not just flatten sequence data into a giant vector?</h2>\\n    <p>\\n      Sequence data is data where order matters: a time series, an audio waveform, a sentence, a video, or a stream of sensor readings.\\n      You can flatten a sequence \\\\(X \\\\in \\\\mathbb{R}^{T \\\\times D}\\\\) into a single vector of length \\\\(T\\\\cdot D\\\\) and feed it to a regular MLP.\\n      It works mechanically, but it\u2019s usually a bad tradeoff:\\n    </p>\\n    <ul>\\n      <li><strong>Parameter explosion:</strong> dense layers connect \u201ceverything to everything\u201d, so weights scale with \\\\((T\\\\cdot D)\\\\).</li>\\n      <li><strong>Ignores sequential structure:</strong> treating time steps as just \u201cfeatures\u201d discards the idea of incremental processing.</li>\\n      <li><strong>Hard to generalize across time:</strong> you\u2019re not explicitly reusing patterns across positions in the sequence.</li>\\n    </ul>\\n\\n    <div class=\\"callout\\">\\n      RNNs exploit the structure: <strong>the same computation repeats at every time step</strong>, just like CNN filters repeat across image locations.\\n    </div>\\n\\n    <h3 id=\\"where-rnns-show-up\\">Where RNNs show up</h3>\\n    <p>\\n      RNNs are useful whenever the meaning of the current item depends on what came before it. Modern Transformers dominate\\n      large-scale language modeling, but the RNN mental model is still important because it explains sequence memory, hidden\\n      state, autoregressive decoding, and the historical path into attention.\\n    </p>\\n    <table>\\n      <thead>\\n        <tr>\\n          <th>Problem family</th>\\n          <th>Why sequence memory matters</th>\\n          <th>Typical output shape</th>\\n        </tr>\\n      </thead>\\n      <tbody>\\n        <tr>\\n          <td>Language modeling</td>\\n          <td>Words depend on earlier words and phrase context.</td>\\n          <td>Next-token distribution at each time step.</td>\\n        </tr>\\n        <tr>\\n          <td>Speech recognition</td>\\n          <td>Audio frames only make sense as an ordered waveform.</td>\\n          <td>Characters, word pieces, or phoneme labels over time.</td>\\n        </tr>\\n        <tr>\\n          <td>Machine translation</td>\\n          <td>The target sentence depends on source order, grammar, and context.</td>\\n          <td>A generated output sequence.</td>\\n        </tr>\\n        <tr>\\n          <td>Stock or demand forecasting</td>\\n          <td>Recent and older time steps can shape the next value.</td>\\n          <td>One future value, a horizon of values, or a class label.</td>\\n        </tr>\\n        <tr>\\n          <td>Music generation</td>\\n          <td>Melody, rhythm, and harmony are sequential patterns.</td>\\n          <td>Next note, chord, token, or audio event.</td>\\n        </tr>\\n        <tr>\\n          <td>Video and sensor streams</td>\\n          <td>Events unfold frame by frame or reading by reading.</td>\\n          <td>Per-step labels, anomaly scores, or a final classification.</td>\\n        </tr>\\n      </tbody>\\n    </table>\\n\\n    <h2 id=\\"2-the-simplest-rnn-unit-elman-unit-equations-and-intuition\\">2) The simplest RNN unit (Elman unit): equations and intuition</h2>\\n\\n    <p>\\n      At each time step \\\\(t\\\\), the RNN consumes an input vector \\\\(x_t \\\\in \\\\mathbb{R}^{D}\\\\) and updates a hidden state\\n      \\\\(h_t \\\\in \\\\mathbb{R}^{M}\\\\). Then it optionally produces an output \\\\(\\\\hat{y}_t\\\\).\\n    </p>\\n\\n    <h3 id=\\"core-equations\\">Core equations</h3>\\n    <p>\\n      A standard \u201cvanilla\u201d RNN does:\\n    </p>\\n    <p>\\n      \\\\[\\n        h_t = \\\\phi(W_{xh}x_t + W_{hh}h_{t-1} + b_h)\\n      \\\\]\\n      \\\\[\\n        \\\\hat{y}_t = \\\\psi(W_{ho}h_t + b_o)\\n      \\\\]\\n    </p>\\n    <p>\\n      Where:\\n    </p>\\n    <ul>\\n      <li>\\\\(W_{xh}\\\\in\\\\mathbb{R}^{M\\\\times D}\\\\): input \u2192 hidden weights</li>\\n      <li>\\\\(W_{hh}\\\\in\\\\mathbb{R}^{M\\\\times M}\\\\): hidden \u2192 hidden (recurrent) weights</li>\\n      <li>\\\\(W_{ho}\\\\in\\\\mathbb{R}^{O\\\\times M}\\\\): hidden \u2192 output weights</li>\\n      <li>\\\\(\\\\phi\\\\): hidden activation (often \\\\(\\\\tanh\\\\) or ReLU); \\\\(\\\\psi\\\\): output activation depends on task</li>\\n      <li>\\\\(h_0\\\\): initial hidden state (often zeros; sometimes learned)</li>\\n    </ul>\\n\\n    <figure>\\n      <svg class=\\"viz\\" viewBox=\\"0 0 960 330\\" role=\\"img\\" aria-label=\\"RNN unrolled through four time steps\\">\\n        <defs>\\n          <marker id=\\"rnn-arrow-blue\\" markerWidth=\\"10\\" markerHeight=\\"10\\" refX=\\"8\\" refY=\\"3\\" orient=\\"auto\\">\\n            <path d=\\"M0,0 L8,3 L0,6 Z\\" fill=\\"#0969da\\"></path>\\n          </marker>\\n          <marker id=\\"rnn-arrow-purple\\" markerWidth=\\"10\\" markerHeight=\\"10\\" refX=\\"8\\" refY=\\"3\\" orient=\\"auto\\">\\n            <path d=\\"M0,0 L8,3 L0,6 Z\\" fill=\\"#8250df\\"></path>\\n          </marker>\\n        </defs>\\n\\n        <text x=\\"30\\" y=\\"34\\" class=\\"title\\">Unrolled RNN: one cell, reused weights, evolving hidden state</text>\\n        <text x=\\"30\\" y=\\"60\\" class=\\"muted\\">The boxes look repeated in the diagram, but they all represent the same learned parameters.</text>\\n\\n        <g>\\n          <rect x=\\"55\\" y=\\"150\\" width=\\"150\\" height=\\"70\\" rx=\\"12\\" fill=\\"#eaf3ff\\" stroke=\\"#0969da\\" stroke-width=\\"1.5\\"></rect>\\n          <text x=\\"130\\" y=\\"177\\" class=\\"label\\" text-anchor=\\"middle\\">RNN cell</text>\\n          <text x=\\"130\\" y=\\"201\\" class=\\"muted\\" text-anchor=\\"middle\\">same Wxh, Whh</text>\\n          <text x=\\"130\\" y=\\"245\\" class=\\"label\\" text-anchor=\\"middle\\">x1</text>\\n          <text x=\\"130\\" y=\\"126\\" class=\\"label\\" text-anchor=\\"middle\\">y1</text>\\n        </g>\\n        <g>\\n          <rect x=\\"285\\" y=\\"150\\" width=\\"150\\" height=\\"70\\" rx=\\"12\\" fill=\\"#f3f8f1\\" stroke=\\"#1a7f37\\" stroke-width=\\"1.5\\"></rect>\\n          <text x=\\"360\\" y=\\"177\\" class=\\"label\\" text-anchor=\\"middle\\">RNN cell</text>\\n          <text x=\\"360\\" y=\\"201\\" class=\\"muted\\" text-anchor=\\"middle\\">same Wxh, Whh</text>\\n          <text x=\\"360\\" y=\\"245\\" class=\\"label\\" text-anchor=\\"middle\\">x2</text>\\n          <text x=\\"360\\" y=\\"126\\" class=\\"label\\" text-anchor=\\"middle\\">y2</text>\\n        </g>\\n        <g>\\n          <rect x=\\"515\\" y=\\"150\\" width=\\"150\\" height=\\"70\\" rx=\\"12\\" fill=\\"#fff8e6\\" stroke=\\"#bf8700\\" stroke-width=\\"1.5\\"></rect>\\n          <text x=\\"590\\" y=\\"177\\" class=\\"label\\" text-anchor=\\"middle\\">RNN cell</text>\\n          <text x=\\"590\\" y=\\"201\\" class=\\"muted\\" text-anchor=\\"middle\\">same Wxh, Whh</text>\\n          <text x=\\"590\\" y=\\"245\\" class=\\"label\\" text-anchor=\\"middle\\">x3</text>\\n          <text x=\\"590\\" y=\\"126\\" class=\\"label\\" text-anchor=\\"middle\\">y3</text>\\n        </g>\\n        <g>\\n          <rect x=\\"745\\" y=\\"150\\" width=\\"150\\" height=\\"70\\" rx=\\"12\\" fill=\\"#f5f0ff\\" stroke=\\"#8250df\\" stroke-width=\\"1.5\\"></rect>\\n          <text x=\\"820\\" y=\\"177\\" class=\\"label\\" text-anchor=\\"middle\\">RNN cell</text>\\n          <text x=\\"820\\" y=\\"201\\" class=\\"muted\\" text-anchor=\\"middle\\">same Wxh, Whh</text>\\n          <text x=\\"820\\" y=\\"245\\" class=\\"label\\" text-anchor=\\"middle\\">x4</text>\\n          <text x=\\"820\\" y=\\"126\\" class=\\"label\\" text-anchor=\\"middle\\">y4</text>\\n        </g>\\n\\n        <path fill=\\"none\\" d=\\"M130 230 L130 222\\" stroke=\\"#0969da\\" stroke-width=\\"2.2\\" marker-end=\\"url(#rnn-arrow-blue)\\"></path>\\n        <path fill=\\"none\\" d=\\"M360 230 L360 222\\" stroke=\\"#0969da\\" stroke-width=\\"2.2\\" marker-end=\\"url(#rnn-arrow-blue)\\"></path>\\n        <path fill=\\"none\\" d=\\"M590 230 L590 222\\" stroke=\\"#0969da\\" stroke-width=\\"2.2\\" marker-end=\\"url(#rnn-arrow-blue)\\"></path>\\n        <path fill=\\"none\\" d=\\"M820 230 L820 222\\" stroke=\\"#0969da\\" stroke-width=\\"2.2\\" marker-end=\\"url(#rnn-arrow-blue)\\"></path>\\n\\n        <path fill=\\"none\\" d=\\"M130 148 L130 132\\" stroke=\\"#1a7f37\\" stroke-width=\\"2.2\\" marker-end=\\"url(#rnn-arrow-blue)\\"></path>\\n        <path fill=\\"none\\" d=\\"M360 148 L360 132\\" stroke=\\"#1a7f37\\" stroke-width=\\"2.2\\" marker-end=\\"url(#rnn-arrow-blue)\\"></path>\\n        <path fill=\\"none\\" d=\\"M590 148 L590 132\\" stroke=\\"#1a7f37\\" stroke-width=\\"2.2\\" marker-end=\\"url(#rnn-arrow-blue)\\"></path>\\n        <path fill=\\"none\\" d=\\"M820 148 L820 132\\" stroke=\\"#1a7f37\\" stroke-width=\\"2.2\\" marker-end=\\"url(#rnn-arrow-blue)\\"></path>\\n\\n        <path fill=\\"none\\" d=\\"M205 185 L285 185\\" stroke=\\"#8250df\\" stroke-width=\\"2.5\\" marker-end=\\"url(#rnn-arrow-purple)\\"></path>\\n        <path fill=\\"none\\" d=\\"M435 185 L515 185\\" stroke=\\"#8250df\\" stroke-width=\\"2.5\\" marker-end=\\"url(#rnn-arrow-purple)\\"></path>\\n        <path fill=\\"none\\" d=\\"M665 185 L745 185\\" stroke=\\"#8250df\\" stroke-width=\\"2.5\\" marker-end=\\"url(#rnn-arrow-purple)\\"></path>\\n        <text x=\\"245\\" y=\\"174\\" class=\\"muted\\" text-anchor=\\"middle\\">h1</text>\\n        <text x=\\"475\\" y=\\"174\\" class=\\"muted\\" text-anchor=\\"middle\\">h2</text>\\n        <text x=\\"705\\" y=\\"174\\" class=\\"muted\\" text-anchor=\\"middle\\">h3</text>\\n\\n        <rect x=\\"44\\" y=\\"278\\" width=\\"868\\" height=\\"34\\" rx=\\"8\\" fill=\\"#f6f8fa\\" stroke=\\"#d0d7de\\"></rect>\\n        <text x=\\"478\\" y=\\"300\\" class=\\"muted\\" text-anchor=\\"middle\\">Input changes at every step. Hidden state changes at every step. Learned weights stay shared.</text>\\n      </svg>\\n      <figcaption>\\n        Unrolling shows the time loop explicitly: current input plus previous hidden state produces the next hidden state.\\n      </figcaption>\\n    </figure>\\n\\n    <h3 id=\\"single-unit-is-used-what-that-really-means\\">\u201cSingle unit is used\u201d: what that really means</h3>\\n    <p>\\n      When people say \u201cthe same unit is used at each time step\u201d, they mean:\\n    </p>\\n    <ul>\\n      <li>You do <strong>not</strong> have a different \\\\(W_{xh}\\\\) for each \\\\(t\\\\).</li>\\n      <li>You do <strong>not</strong> have a different \\\\(W_{hh}\\\\) for each \\\\(t\\\\).</li>\\n      <li>You reuse the <strong>same</strong> weights and biases at every step: that\u2019s <strong>parameter sharing through time</strong>.</li>\\n    </ul>\\n    <p>\\n      The only thing that changes over time is the <em>data</em> (\\\\(x_t\\\\)) and the <em>state</em> (\\\\(h_{t-1}\\\\to h_t\\\\)).\\n      This is exactly why RNNs can have far fewer parameters than a flattened dense design.\\n    </p>\\n    <p>\\n      Cost nuance: the <em>parameter count</em> does not grow with \\\\(T\\\\), but the <em>computation</em> still runs once per time step,\\n      and training stores intermediate states for backpropagation through time. Long sequences can still be expensive.\\n    </p>\\n\\n    <h2 id=\\"3-many-to-one-vs-many-to-many-why-you-might-ignore-most-outputs\\">3) Many-to-one vs many-to-many: why you might \u201cignore\u201d most outputs</h2>\\n    <p>\\n      You can compute \\\\(\\\\hat{y}_t\\\\) at every step, but whether you <em>use</em> them depends on the task:\\n    </p>\\n    <ul>\\n      <li><strong>Many-to-one:</strong> sentiment of a sentence \u2192 use only \\\\(\\\\hat{y}_T\\\\)</li>\\n      <li><strong>Many-to-many:</strong> label each time step (e.g., tagging) \u2192 use all \\\\(\\\\hat{y}_t\\\\)</li>\\n      <li><strong>Seq2seq (translation):</strong> outputs are also a sequence \u2192 you need stepwise predictions</li>\\n    </ul>\\n\\n    <figure>\\n      <svg class=\\"viz\\" viewBox=\\"0 0 980 375\\" role=\\"img\\" aria-label=\\"RNN output patterns for many-to-one many-to-many and seq2seq tasks\\">\\n        <defs>\\n          <marker id=\\"rnn-output-arrow\\" markerWidth=\\"10\\" markerHeight=\\"10\\" refX=\\"8\\" refY=\\"3\\" orient=\\"auto\\">\\n            <path d=\\"M0,0 L8,3 L0,6 Z\\" fill=\\"#0969da\\"></path>\\n          </marker>\\n        </defs>\\n        <text x=\\"30\\" y=\\"34\\" class=\\"title\\">Same recurrent cell, different output usage</text>\\n        <text x=\\"30\\" y=\\"60\\" class=\\"muted\\">The RNN can emit at every step; the task decides which outputs become supervised predictions.</text>\\n\\n        <g transform=\\"translate(38,100)\\">\\n          <text x=\\"140\\" y=\\"-18\\" class=\\"label\\" text-anchor=\\"middle\\">Many-to-one</text>\\n          <rect x=\\"0\\" y=\\"35\\" width=\\"56\\" height=\\"42\\" rx=\\"9\\" fill=\\"#eaf3ff\\" stroke=\\"#0969da\\"></rect>\\n          <rect x=\\"74\\" y=\\"35\\" width=\\"56\\" height=\\"42\\" rx=\\"9\\" fill=\\"#eaf3ff\\" stroke=\\"#0969da\\"></rect>\\n          <rect x=\\"148\\" y=\\"35\\" width=\\"56\\" height=\\"42\\" rx=\\"9\\" fill=\\"#eaf3ff\\" stroke=\\"#0969da\\"></rect>\\n          <rect x=\\"222\\" y=\\"35\\" width=\\"56\\" height=\\"42\\" rx=\\"9\\" fill=\\"#eaf3ff\\" stroke=\\"#0969da\\"></rect>\\n          <path fill=\\"none\\" d=\\"M56 56 L74 56 M130 56 L148 56 M204 56 L222 56\\" stroke=\\"#0969da\\" stroke-width=\\"2.2\\" marker-end=\\"url(#rnn-output-arrow)\\"></path>\\n          <rect x=\\"222\\" y=\\"122\\" width=\\"56\\" height=\\"42\\" rx=\\"9\\" fill=\\"#f3f8f1\\" stroke=\\"#1a7f37\\"></rect>\\n          <path fill=\\"none\\" d=\\"M250 77 L250 122\\" stroke=\\"#1a7f37\\" stroke-width=\\"2.2\\" marker-end=\\"url(#rnn-output-arrow)\\"></path>\\n          <text x=\\"28\\" y=\\"62\\" class=\\"label\\" text-anchor=\\"middle\\">h1</text>\\n          <text x=\\"102\\" y=\\"62\\" class=\\"label\\" text-anchor=\\"middle\\">h2</text>\\n          <text x=\\"176\\" y=\\"62\\" class=\\"label\\" text-anchor=\\"middle\\">h3</text>\\n          <text x=\\"250\\" y=\\"62\\" class=\\"label\\" text-anchor=\\"middle\\">hT</text>\\n          <text x=\\"250\\" y=\\"149\\" class=\\"label\\" text-anchor=\\"middle\\">sentiment</text>\\n        </g>\\n\\n        <g transform=\\"translate(356,100)\\">\\n          <text x=\\"140\\" y=\\"-18\\" class=\\"label\\" text-anchor=\\"middle\\">Many-to-many</text>\\n          <rect x=\\"0\\" y=\\"35\\" width=\\"56\\" height=\\"42\\" rx=\\"9\\" fill=\\"#f5f0ff\\" stroke=\\"#8250df\\"></rect>\\n          <rect x=\\"74\\" y=\\"35\\" width=\\"56\\" height=\\"42\\" rx=\\"9\\" fill=\\"#f5f0ff\\" stroke=\\"#8250df\\"></rect>\\n          <rect x=\\"148\\" y=\\"35\\" width=\\"56\\" height=\\"42\\" rx=\\"9\\" fill=\\"#f5f0ff\\" stroke=\\"#8250df\\"></rect>\\n          <rect x=\\"222\\" y=\\"35\\" width=\\"56\\" height=\\"42\\" rx=\\"9\\" fill=\\"#f5f0ff\\" stroke=\\"#8250df\\"></rect>\\n          <path fill=\\"none\\" d=\\"M56 56 L74 56 M130 56 L148 56 M204 56 L222 56\\" stroke=\\"#8250df\\" stroke-width=\\"2.2\\" marker-end=\\"url(#rnn-output-arrow)\\"></path>\\n          <g fill=\\"#fff8e6\\" stroke=\\"#bf8700\\">\\n            <rect x=\\"0\\" y=\\"122\\" width=\\"56\\" height=\\"42\\" rx=\\"9\\"></rect>\\n            <rect x=\\"74\\" y=\\"122\\" width=\\"56\\" height=\\"42\\" rx=\\"9\\"></rect>\\n            <rect x=\\"148\\" y=\\"122\\" width=\\"56\\" height=\\"42\\" rx=\\"9\\"></rect>\\n            <rect x=\\"222\\" y=\\"122\\" width=\\"56\\" height=\\"42\\" rx=\\"9\\"></rect>\\n          </g>\\n          <path fill=\\"none\\" d=\\"M28 77 L28 122 M102 77 L102 122 M176 77 L176 122 M250 77 L250 122\\" stroke=\\"#bf8700\\" stroke-width=\\"2.1\\" marker-end=\\"url(#rnn-output-arrow)\\"></path>\\n          <text x=\\"28\\" y=\\"62\\" class=\\"label\\" text-anchor=\\"middle\\">h1</text>\\n          <text x=\\"102\\" y=\\"62\\" class=\\"label\\" text-anchor=\\"middle\\">h2</text>\\n          <text x=\\"176\\" y=\\"62\\" class=\\"label\\" text-anchor=\\"middle\\">h3</text>\\n          <text x=\\"250\\" y=\\"62\\" class=\\"label\\" text-anchor=\\"middle\\">hT</text>\\n          <text x=\\"140\\" y=\\"151\\" class=\\"muted\\" text-anchor=\\"middle\\">one label per step</text>\\n        </g>\\n\\n        <g transform=\\"translate(690,100)\\">\\n          <text x=\\"126\\" y=\\"-18\\" class=\\"label\\" text-anchor=\\"middle\\">Seq2seq</text>\\n          <rect x=\\"0\\" y=\\"35\\" width=\\"72\\" height=\\"42\\" rx=\\"9\\" fill=\\"#eaf3ff\\" stroke=\\"#0969da\\"></rect>\\n          <rect x=\\"88\\" y=\\"35\\" width=\\"72\\" height=\\"42\\" rx=\\"9\\" fill=\\"#eaf3ff\\" stroke=\\"#0969da\\"></rect>\\n          <rect x=\\"176\\" y=\\"35\\" width=\\"72\\" height=\\"42\\" rx=\\"9\\" fill=\\"#eaf3ff\\" stroke=\\"#0969da\\"></rect>\\n          <path fill=\\"none\\" d=\\"M72 56 L88 56 M160 56 L176 56\\" stroke=\\"#0969da\\" stroke-width=\\"2.2\\" marker-end=\\"url(#rnn-output-arrow)\\"></path>\\n          <rect x=\\"66\\" y=\\"110\\" width=\\"116\\" height=\\"46\\" rx=\\"11\\" fill=\\"#f5f0ff\\" stroke=\\"#8250df\\"></rect>\\n          <path fill=\\"none\\" d=\\"M124 77 L124 110\\" stroke=\\"#8250df\\" stroke-width=\\"2.2\\" marker-end=\\"url(#rnn-output-arrow)\\"></path>\\n          <rect x=\\"0\\" y=\\"190\\" width=\\"72\\" height=\\"42\\" rx=\\"9\\" fill=\\"#f3f8f1\\" stroke=\\"#1a7f37\\"></rect>\\n          <rect x=\\"88\\" y=\\"190\\" width=\\"72\\" height=\\"42\\" rx=\\"9\\" fill=\\"#f3f8f1\\" stroke=\\"#1a7f37\\"></rect>\\n          <rect x=\\"176\\" y=\\"190\\" width=\\"72\\" height=\\"42\\" rx=\\"9\\" fill=\\"#f3f8f1\\" stroke=\\"#1a7f37\\"></rect>\\n          <path fill=\\"none\\" d=\\"M124 156 L124 190\\" stroke=\\"#1a7f37\\" stroke-width=\\"2.2\\" marker-end=\\"url(#rnn-output-arrow)\\"></path>\\n          <text x=\\"124\\" y=\\"140\\" class=\\"label\\" text-anchor=\\"middle\\">context</text>\\n          <text x=\\"36\\" y=\\"217\\" class=\\"label\\" text-anchor=\\"middle\\">y1</text>\\n          <text x=\\"124\\" y=\\"217\\" class=\\"label\\" text-anchor=\\"middle\\">y2</text>\\n          <text x=\\"212\\" y=\\"217\\" class=\\"label\\" text-anchor=\\"middle\\">y3</text>\\n          <text x=\\"124\\" y=\\"258\\" class=\\"muted\\" text-anchor=\\"middle\\">target sequence</text>\\n        </g>\\n      </svg>\\n      <figcaption>\\n        Many-to-one, many-to-many, and seq2seq are not different definitions of an RNN. They are different ways of using the outputs.\\n      </figcaption>\\n    </figure>\\n\\n    <h3 id=\\"compact-rnn-summary\\">Compact RNN summary</h3>\\n    <table>\\n      <thead>\\n        <tr>\\n          <th>Feature</th>\\n          <th>Meaning</th>\\n        </tr>\\n      </thead>\\n      <tbody>\\n        <tr>\\n          <td>Input type</td>\\n          <td>Ordered data such as text, speech, time series, video frames, event streams, or sensor readings.</td>\\n        </tr>\\n        <tr>\\n          <td>Core mechanism</td>\\n          <td>Reuse one learned cell through time while carrying hidden state forward.</td>\\n        </tr>\\n        <tr>\\n          <td>Memory</td>\\n          <td>The hidden state \\\\(h_t\\\\) summarizes what the model has retained up to step \\\\(t\\\\).</td>\\n        </tr>\\n        <tr>\\n          <td>Output</td>\\n          <td>Can be one final prediction, one prediction per time step, or a generated sequence from a decoder.</td>\\n        </tr>\\n        <tr>\\n          <td>Strength</td>\\n          <td>Handles variable-length ordered inputs with shared parameters rather than a fixed flattened vector.</td>\\n        </tr>\\n        <tr>\\n          <td>Main challenges</td>\\n          <td>Vanishing/exploding gradients, sequential training cost, and pressure to compress long context into state.</td>\\n        </tr>\\n        <tr>\\n          <td>Common variants</td>\\n          <td>LSTM, GRU, bidirectional RNN/GRU/LSTM, encoder-decoder RNNs, and attention-augmented seq2seq models.</td>\\n        </tr>\\n      </tbody>\\n    </table>\\n\\n    <h2 id=\\"4-practical-seq2seq-example-translating-my-name-is-dinesh\\">4) Practical seq2seq example: translating \u201cmy name is dinesh\u201d</h2>\\n    <p>\\n      A useful way to understand RNN inputs and outputs is to walk through a tiny machine-translation problem:\\n      translate <strong>\u201cmy name is dinesh\u201d</strong> into <strong>\u201cmon nom est dinesh\u201d</strong>. A classic RNN translation\\n      system uses an <strong>encoder</strong> RNN to read the source sentence and a <strong>decoder</strong> RNN to generate\\n      the target sentence. The French target is a literal teaching example; an idiomatic translation might be\\n      <em>\u201cje m\u2019appelle Dinesh\u201d</em>, but the literal four-token target makes the step-by-step alignment easier to see.\\n    </p>\\n\\n    <div class=\\"callout blue\\">\\n      <strong>What the model sees:</strong> not raw text. Text is tokenized into IDs, IDs are looked up in an embedding table,\\n      and the RNN receives one dense vector per time step.\\n    </div>\\n\\n    <h3 id=\\"step-a-text-becomes-tokens-token-ids-then-embeddings\\">Step A: text becomes tokens, token IDs, then embeddings</h3>\\n    <table>\\n      <thead>\\n        <tr>\\n          <th>Stage</th>\\n          <th>Example</th>\\n          <th>Shape / meaning</th>\\n        </tr>\\n      </thead>\\n      <tbody>\\n        <tr>\\n          <td>Source tokens</td>\\n          <td><code>[\\"my\\", \\"name\\", \\"is\\", \\"dinesh\\", \\"&lt;EOS&gt;\\"]</code></td>\\n          <td>A finite sequence ending with an explicit end-of-sentence marker.</td>\\n        </tr>\\n        <tr>\\n          <td>Token IDs</td>\\n          <td><code>[17, 241, 9, 5021, 2]</code></td>\\n          <td>Integer vocabulary indices. The actual numbers are arbitrary.</td>\\n        </tr>\\n        <tr>\\n          <td>Embeddings</td>\\n          <td><code>[0.12, -0.33, 0.45, ...]</code> for each token</td>\\n          <td>If embedding size is \\\\(D=300\\\\), each time step gives the RNN one vector in \\\\(\\\\mathbb{R}^{300}\\\\).</td>\\n        </tr>\\n        <tr>\\n          <td>Padded batch</td>\\n          <td><code>[\\"my\\", \\"name\\", \\"is\\", \\"dinesh\\", \\"&lt;EOS&gt;\\", \\"&lt;PAD&gt;\\", ...]</code></td>\\n          <td>Padding makes examples in a batch the same length. Padding positions are masked or ignored; they are not extra meaning.</td>\\n        </tr>\\n      </tbody>\\n    </table>\\n\\n    <pre><code class=\\"language-python\\">import torch\\nimport torch.nn as nn\\n\\nsrc_tokens = [\\"my\\", \\"name\\", \\"is\\", \\"dinesh\\", \\"&lt;EOS&gt;\\", \\"&lt;PAD&gt;\\", \\"&lt;PAD&gt;\\", \\"&lt;PAD&gt;\\", \\"&lt;PAD&gt;\\", \\"&lt;PAD&gt;\\"]\\nsrc_ids = torch.tensor([[17, 241, 9, 5021, 2, 0, 0, 0, 0, 0]])  # (batch=1, T=10)\\n\\nembedding = nn.Embedding(num_embeddings=10_000, embedding_dim=300, padding_idx=0)\\nx = embedding(src_ids)  # (1, 10, 300)\\n\\nprint(x.shape)  # one 300-dimensional input vector per time step</code></pre>\\n\\n    <h3 id=\\"step-b-encoder-rnn-reads-the-english-sentence\\">Step B: encoder RNN reads the English sentence</h3>\\n    <p>\\n      The encoder consumes one embedding at a time and updates hidden state. If a 10-step tensor is used for batching,\\n      the meaningful tokens occupy the early positions and the remaining positions are padding. In production code, lengths\\n      or masks prevent padding from contributing to the loss and, depending on implementation, from changing the final state.\\n    </p>\\n    <table>\\n      <thead>\\n        <tr>\\n          <th>Encoder step</th>\\n          <th>Input token</th>\\n          <th>Hidden-state interpretation</th>\\n        </tr>\\n      </thead>\\n      <tbody>\\n        <tr><td>1</td><td><code>my</code></td><td>Starts the sentence and records a possessive cue.</td></tr>\\n        <tr><td>2</td><td><code>name</code></td><td>Builds the phrase \u201cmy name\u201d and the identity context.</td></tr>\\n        <tr><td>3</td><td><code>is</code></td><td>Adds the grammatical relation that links phrase to value.</td></tr>\\n        <tr><td>4</td><td><code>dinesh</code></td><td>Stores the name entity that should be copied or transliterated.</td></tr>\\n        <tr><td>5</td><td><code>&lt;EOS&gt;</code></td><td>Marks that the source sentence is complete.</td></tr>\\n        <tr><td>6-10</td><td><code>&lt;PAD&gt;</code></td><td>Ignored by masks/lengths; present only so the batch has a rectangular tensor shape.</td></tr>\\n      </tbody>\\n    </table>\\n\\n    <h3 id=\\"step-c-decoder-rnn-generates-french-one-token-at-a-time\\">Step C: decoder RNN generates French one token at a time</h3>\\n    <p>\\n      The decoder starts from the encoder\u2019s final meaning representation. At each step it receives the previous French token\\n      and predicts a probability distribution over the French vocabulary. During training, it often receives the true previous\\n      token as input (<em>teacher forcing</em>). During inference, it feeds its own previous prediction back in.\\n    </p>\\n    <table>\\n      <thead>\\n        <tr>\\n          <th>Decoder step</th>\\n          <th>Decoder input</th>\\n          <th>Prediction</th>\\n          <th>Why it happens</th>\\n        </tr>\\n      </thead>\\n      <tbody>\\n        <tr><td>1</td><td><code>&lt;SOS&gt;</code></td><td><code>mon</code></td><td>The start token asks the decoder to begin the translation.</td></tr>\\n        <tr><td>2</td><td><code>mon</code></td><td><code>nom</code></td><td>The decoder continues the French phrase \u201cmon nom\u201d.</td></tr>\\n        <tr><td>3</td><td><code>nom</code></td><td><code>est</code></td><td>The model emits the linking verb.</td></tr>\\n        <tr><td>4</td><td><code>est</code></td><td><code>dinesh</code></td><td>The name entity is carried through from the encoded source context.</td></tr>\\n        <tr><td>5</td><td><code>dinesh</code></td><td><code>&lt;EOS&gt;</code></td><td>The decoder decides the target sentence is complete.</td></tr>\\n        <tr><td>6-10</td><td><code>&lt;PAD&gt;</code></td><td>ignored</td><td>Padding positions are ignored when batching fixed-length targets.</td></tr>\\n      </tbody>\\n    </table>\\n\\n    <figure>\\n      <svg class=\\"viz\\" viewBox=\\"0 0 960 430\\" role=\\"img\\" aria-label=\\"Encoder decoder RNN translation flow\\">\\n        <defs>\\n          <marker id=\\"seq2seq-arrow\\" markerWidth=\\"10\\" markerHeight=\\"10\\" refX=\\"8\\" refY=\\"3\\" orient=\\"auto\\">\\n            <path d=\\"M0,0 L8,3 L0,6 Z\\" fill=\\"#0969da\\"></path>\\n          </marker>\\n          <marker id=\\"seq2seq-arrow-purple\\" markerWidth=\\"10\\" markerHeight=\\"10\\" refX=\\"8\\" refY=\\"3\\" orient=\\"auto\\">\\n            <path d=\\"M0,0 L8,3 L0,6 Z\\" fill=\\"#8250df\\"></path>\\n          </marker>\\n        </defs>\\n\\n        <text x=\\"30\\" y=\\"34\\" class=\\"title\\">Encoder-decoder RNN for translation</text>\\n        <text x=\\"30\\" y=\\"60\\" class=\\"muted\\">The encoder reads English. The decoder writes French. Hidden state is the bridge.</text>\\n\\n        <text x=\\"82\\" y=\\"100\\" class=\\"label\\" text-anchor=\\"middle\\">English tokens</text>\\n        <g>\\n          <rect x=\\"32\\" y=\\"118\\" width=\\"100\\" height=\\"42\\" rx=\\"10\\" fill=\\"#eaf3ff\\" stroke=\\"#0969da\\"></rect>\\n          <rect x=\\"142\\" y=\\"118\\" width=\\"100\\" height=\\"42\\" rx=\\"10\\" fill=\\"#eaf3ff\\" stroke=\\"#0969da\\"></rect>\\n          <rect x=\\"252\\" y=\\"118\\" width=\\"100\\" height=\\"42\\" rx=\\"10\\" fill=\\"#eaf3ff\\" stroke=\\"#0969da\\"></rect>\\n          <rect x=\\"362\\" y=\\"118\\" width=\\"100\\" height=\\"42\\" rx=\\"10\\" fill=\\"#eaf3ff\\" stroke=\\"#0969da\\"></rect>\\n          <rect x=\\"472\\" y=\\"118\\" width=\\"100\\" height=\\"42\\" rx=\\"10\\" fill=\\"#f6f8fa\\" stroke=\\"#d0d7de\\"></rect>\\n          <text x=\\"82\\" y=\\"145\\" class=\\"label\\" text-anchor=\\"middle\\">my</text>\\n          <text x=\\"192\\" y=\\"145\\" class=\\"label\\" text-anchor=\\"middle\\">name</text>\\n          <text x=\\"302\\" y=\\"145\\" class=\\"label\\" text-anchor=\\"middle\\">is</text>\\n          <text x=\\"412\\" y=\\"145\\" class=\\"label\\" text-anchor=\\"middle\\">dinesh</text>\\n          <text x=\\"522\\" y=\\"145\\" class=\\"muted\\" text-anchor=\\"middle\\">EOS</text>\\n        </g>\\n\\n        <g>\\n          <rect x=\\"78\\" y=\\"205\\" width=\\"100\\" height=\\"54\\" rx=\\"12\\" fill=\\"#dbeafe\\" stroke=\\"#0969da\\" stroke-width=\\"1.5\\"></rect>\\n          <rect x=\\"198\\" y=\\"205\\" width=\\"100\\" height=\\"54\\" rx=\\"12\\" fill=\\"#dbeafe\\" stroke=\\"#0969da\\" stroke-width=\\"1.5\\"></rect>\\n          <rect x=\\"318\\" y=\\"205\\" width=\\"100\\" height=\\"54\\" rx=\\"12\\" fill=\\"#dbeafe\\" stroke=\\"#0969da\\" stroke-width=\\"1.5\\"></rect>\\n          <rect x=\\"438\\" y=\\"205\\" width=\\"100\\" height=\\"54\\" rx=\\"12\\" fill=\\"#dbeafe\\" stroke=\\"#0969da\\" stroke-width=\\"1.5\\"></rect>\\n          <text x=\\"128\\" y=\\"236\\" class=\\"label\\" text-anchor=\\"middle\\">enc</text>\\n          <text x=\\"248\\" y=\\"236\\" class=\\"label\\" text-anchor=\\"middle\\">enc</text>\\n          <text x=\\"368\\" y=\\"236\\" class=\\"label\\" text-anchor=\\"middle\\">enc</text>\\n          <text x=\\"488\\" y=\\"236\\" class=\\"label\\" text-anchor=\\"middle\\">enc</text>\\n          <path fill=\\"none\\" d=\\"M178 232 L198 232\\" stroke=\\"#0969da\\" stroke-width=\\"2.2\\" marker-end=\\"url(#seq2seq-arrow)\\"></path>\\n          <path fill=\\"none\\" d=\\"M298 232 L318 232\\" stroke=\\"#0969da\\" stroke-width=\\"2.2\\" marker-end=\\"url(#seq2seq-arrow)\\"></path>\\n          <path fill=\\"none\\" d=\\"M418 232 L438 232\\" stroke=\\"#0969da\\" stroke-width=\\"2.2\\" marker-end=\\"url(#seq2seq-arrow)\\"></path>\\n        </g>\\n\\n        <rect x=\\"590\\" y=\\"197\\" width=\\"150\\" height=\\"70\\" rx=\\"14\\" fill=\\"#f5f0ff\\" stroke=\\"#8250df\\" stroke-width=\\"1.7\\"></rect>\\n        <text x=\\"665\\" y=\\"225\\" class=\\"label\\" text-anchor=\\"middle\\">context</text>\\n        <text x=\\"665\\" y=\\"247\\" class=\\"muted\\" text-anchor=\\"middle\\">final hidden state</text>\\n        <path fill=\\"none\\" d=\\"M538 232 L590 232\\" stroke=\\"#8250df\\" stroke-width=\\"2.5\\" marker-end=\\"url(#seq2seq-arrow-purple)\\"></path>\\n\\n        <g>\\n          <rect x=\\"70\\" y=\\"318\\" width=\\"105\\" height=\\"46\\" rx=\\"10\\" fill=\\"#f3f8f1\\" stroke=\\"#1a7f37\\"></rect>\\n          <rect x=\\"190\\" y=\\"318\\" width=\\"105\\" height=\\"46\\" rx=\\"10\\" fill=\\"#f3f8f1\\" stroke=\\"#1a7f37\\"></rect>\\n          <rect x=\\"310\\" y=\\"318\\" width=\\"105\\" height=\\"46\\" rx=\\"10\\" fill=\\"#f3f8f1\\" stroke=\\"#1a7f37\\"></rect>\\n          <rect x=\\"430\\" y=\\"318\\" width=\\"105\\" height=\\"46\\" rx=\\"10\\" fill=\\"#f3f8f1\\" stroke=\\"#1a7f37\\"></rect>\\n          <rect x=\\"550\\" y=\\"318\\" width=\\"105\\" height=\\"46\\" rx=\\"10\\" fill=\\"#f6f8fa\\" stroke=\\"#d0d7de\\"></rect>\\n          <text x=\\"122\\" y=\\"346\\" class=\\"label\\" text-anchor=\\"middle\\">mon</text>\\n          <text x=\\"242\\" y=\\"346\\" class=\\"label\\" text-anchor=\\"middle\\">nom</text>\\n          <text x=\\"362\\" y=\\"346\\" class=\\"label\\" text-anchor=\\"middle\\">est</text>\\n          <text x=\\"482\\" y=\\"346\\" class=\\"label\\" text-anchor=\\"middle\\">dinesh</text>\\n          <text x=\\"602\\" y=\\"346\\" class=\\"muted\\" text-anchor=\\"middle\\">EOS</text>\\n          <text x=\\"362\\" y=\\"394\\" class=\\"muted\\" text-anchor=\\"middle\\">French tokens are produced one step at a time from vocabulary probabilities.</text>\\n        </g>\\n\\n        <path fill=\\"none\\" d=\\"M665 267 C665 297 630 308 600 318\\" stroke=\\"#8250df\\" stroke-width=\\"2.5\\" marker-end=\\"url(#seq2seq-arrow-purple)\\"></path>\\n        <path fill=\\"none\\" d=\\"M175 341 L190 341\\" stroke=\\"#1a7f37\\" stroke-width=\\"2.1\\" marker-end=\\"url(#seq2seq-arrow)\\"></path>\\n        <path fill=\\"none\\" d=\\"M295 341 L310 341\\" stroke=\\"#1a7f37\\" stroke-width=\\"2.1\\" marker-end=\\"url(#seq2seq-arrow)\\"></path>\\n        <path fill=\\"none\\" d=\\"M415 341 L430 341\\" stroke=\\"#1a7f37\\" stroke-width=\\"2.1\\" marker-end=\\"url(#seq2seq-arrow)\\"></path>\\n        <path fill=\\"none\\" d=\\"M535 341 L550 341\\" stroke=\\"#1a7f37\\" stroke-width=\\"2.1\\" marker-end=\\"url(#seq2seq-arrow)\\"></path>\\n      </svg>\\n      <figcaption>\\n        A classic seq2seq RNN compresses the source into hidden state, then decodes the target sequence token by token.\\n        Attention improves this by letting the decoder look back at specific encoder states instead of relying only on one final vector.\\n      </figcaption>\\n    </figure>\\n\\n    <pre><code class=\\"language-python\\"># Decoder inference sketch: generate French tokens autoregressively.\\n# This is conceptual pseudocode; real systems use batching, masks, beam search,\\n# and often attention over all encoder states.\\n\\nprev_token = SOS_ID\\nhidden = encoder_final_hidden\\ngenerated = []\\n\\nfor _ in range(max_target_len):\\n    prev_emb = target_embedding(torch.tensor([[prev_token]]))  # (1, 1, D)\\n    decoder_out, hidden = decoder_rnn(prev_emb, hidden)\\n    logits = output_projection(decoder_out[:, -1, :])          # (1, vocab_size)\\n    next_token = int(logits.argmax(dim=-1).item())\\n\\n    if next_token == EOS_ID:\\n        break\\n\\n    generated.append(next_token)\\n    prev_token = next_token  # feed the model\'s own prediction back in</code></pre>\\n\\n    <div class=\\"callout green\\">\\n      <strong>What actually learns:</strong> gradients flow through the unrolled encoder and decoder during training.\\n      The model adjusts embeddings, recurrent weights, and output-projection weights so that the right target token receives\\n      higher probability at each decoder step.\\n    </div>\\n\\n    <h2 id=\\"5-pseudocode-forward-pass-through-a-sequence\\">5) Pseudocode: forward pass through a sequence</h2>\\n    <pre><code class=\\"language-python\\"># Given:\\n#   X: shape (T, D)\\n#   h0: shape (M,)   (often zeros)\\n#   weights: W_xh (M, D), W_hh (M, M), b_h (M,)\\n#            W_ho (O, M), b_o (O,)\\n# Returns:\\n#   y_hats: list of length T, each element shape (O,)\\n\\nh = h0\\ny_hats = []\\nfor t in range(T):\\n    h = tanh(W_xh @ X[t] + W_hh @ h + b_h)   # hidden update\\n    y = softmax(W_ho @ h + b_o)              # output (for classification)\\n    y_hats.append(y)\\n\\n# For many-to-one tasks, you would use y_hats[-1] and ignore the rest.</code></pre>\\n\\n    <h2 id=\\"6-cost-savings-rnn-vs-flattened-ann\\">6) Cost savings: RNN vs flattened ANN</h2>\\n    <p>\\n      Let:\\n    </p>\\n    <ul>\\n      <li>\\\\(T\\\\) = sequence length</li>\\n      <li>\\\\(D\\\\) = features per time step</li>\\n      <li>\\\\(M\\\\) = hidden size</li>\\n      <li>\\\\(O\\\\) = output size (e.g., \\\\(O=1\\\\) for binary classification/logit)</li>\\n    </ul>\\n\\n    <h3 id=\\"flattened-ann-dense-everything-to-everything\\">Flattened ANN (dense \u201ceverything-to-everything\u201d)</h3>\\n    <p>\\n      If you flatten, input size is \\\\(T\\\\cdot D\\\\). If you also keep a hidden representation for each time step\\n      (as in the transcript\u2019s comparison), hidden size becomes \\\\(T\\\\cdot M\\\\).\\n    </p>\\n    <p>\\n      Approx weights (ignoring biases):\\n      \\\\[\\n        (T D)(T M) + (T M)O\\n      \\\\]\\n    </p>\\n\\n    <h3 id=\\"rnn-shared-weights-through-time\\">RNN (shared weights through time)</h3>\\n    <p>\\n      Weights are independent of \\\\(T\\\\):\\n      \\\\[\\n        W_{xh}: M D,\\\\quad W_{hh}: M^2,\\\\quad W_{ho}: O M\\n      \\\\]\\n      Total:\\n      \\\\[\\n        MD + M^2 + OM\\n      \\\\]\\n    </p>\\n    <p class=\\"muted\\">\\n      This comparison is about trainable parameters. Runtime still scales with sequence length because the recurrent update is applied\\n      at every step. For many-to-one tasks, the output head may only be applied to the final hidden state; for many-to-many tasks, it is\\n      applied at each step, which changes compute but not the shared recurrent parameter count.\\n    </p>\\n\\n    <div class=\\"callout\\">\\n      <strong>Key win:</strong> RNN parameter count does <em>not</em> grow with sequence length \\\\(T\\\\) the way a flattened dense model does.\\n    </div>\\n\\n    <figure>\\n      <svg class=\\"viz\\" viewBox=\\"0 0 980 270\\" role=\\"img\\" aria-label=\\"Parameter growth comparison between flattened ANN and RNN\\">\\n        <defs>\\n          <marker id=\\"rnn-param-arrow\\" markerWidth=\\"10\\" markerHeight=\\"10\\" refX=\\"8\\" refY=\\"3\\" orient=\\"auto\\">\\n            <path d=\\"M0,0 L8,3 L0,6 Z\\" fill=\\"#8250df\\"></path>\\n          </marker>\\n        </defs>\\n        <text x=\\"30\\" y=\\"34\\" class=\\"title\\">Parameter sharing is the first RNN efficiency idea</text>\\n        <text x=\\"30\\" y=\\"60\\" class=\\"muted\\">Flattened sequence models allocate weights for positions; recurrent models reuse one transition rule.</text>\\n\\n        <g transform=\\"translate(64,104)\\">\\n          <text x=\\"180\\" y=\\"-18\\" class=\\"label\\" text-anchor=\\"middle\\">Flattened ANN view</text>\\n          <rect x=\\"0\\" y=\\"15\\" width=\\"122\\" height=\\"54\\" rx=\\"10\\" fill=\\"#fff8e6\\" stroke=\\"#bf8700\\"></rect>\\n          <rect x=\\"142\\" y=\\"15\\" width=\\"122\\" height=\\"54\\" rx=\\"10\\" fill=\\"#fff8e6\\" stroke=\\"#bf8700\\"></rect>\\n          <rect x=\\"284\\" y=\\"15\\" width=\\"122\\" height=\\"54\\" rx=\\"10\\" fill=\\"#fff8e6\\" stroke=\\"#bf8700\\"></rect>\\n          <text x=\\"61\\" y=\\"48\\" class=\\"label\\" text-anchor=\\"middle\\">position 1</text>\\n          <text x=\\"203\\" y=\\"48\\" class=\\"label\\" text-anchor=\\"middle\\">position 2</text>\\n          <text x=\\"345\\" y=\\"48\\" class=\\"label\\" text-anchor=\\"middle\\">position T</text>\\n          <path fill=\\"none\\" d=\\"M61 69 L61 114 M203 69 L203 114 M345 69 L345 114\\" stroke=\\"#bf8700\\" stroke-width=\\"2.1\\" marker-end=\\"url(#rnn-param-arrow)\\"></path>\\n          <text x=\\"203\\" y=\\"145\\" class=\\"muted\\" text-anchor=\\"middle\\">more positions imply more position-specific weights</text>\\n        </g>\\n\\n        <g transform=\\"translate(560,104)\\">\\n          <text x=\\"170\\" y=\\"-18\\" class=\\"label\\" text-anchor=\\"middle\\">RNN view</text>\\n          <rect x=\\"28\\" y=\\"15\\" width=\\"142\\" height=\\"58\\" rx=\\"12\\" fill=\\"#eaf3ff\\" stroke=\\"#0969da\\"></rect>\\n          <text x=\\"99\\" y=\\"49\\" class=\\"label\\" text-anchor=\\"middle\\">same cell</text>\\n          <path d=\\"M175 44 C250 0 325 0 325 44 C325 88 250 88 175 44\\" stroke=\\"#0969da\\" stroke-width=\\"2.4\\" fill=\\"none\\" marker-end=\\"url(#rnn-param-arrow)\\"></path>\\n          <text x=\\"252\\" y=\\"118\\" class=\\"muted\\" text-anchor=\\"middle\\">run again with new x_t and h_{t-1}</text>\\n          <rect x=\\"28\\" y=\\"146\\" width=\\"304\\" height=\\"38\\" rx=\\"10\\" fill=\\"#f3f8f1\\" stroke=\\"#1a7f37\\"></rect>\\n          <text x=\\"180\\" y=\\"170\\" class=\\"label\\" text-anchor=\\"middle\\">parameters stay MD + M^2 + OM</text>\\n        </g>\\n      </svg>\\n      <figcaption>\\n        RNNs save parameters by reusing the same weights at each time step. Computation still grows with sequence length, but the learned recurrent matrices do not.\\n      </figcaption>\\n    </figure>\\n\\n    <h3 id=\\"concrete-example-python-code-and-a-plot\\">Concrete example + Python code (and a plot)</h3>\\n    <p>\\n      Example: \\\\(T=100\\\\), \\\\(D=10\\\\), \\\\(M=15\\\\), \\\\(O=1\\\\).\\n    </p>\\n\\n    <pre><code class=\\"language-python\\">import numpy as np\\nimport matplotlib.pyplot as plt\\n\\ndef ann_params_flat(T, D, M, O):\\n    # Transcript-style comparison: hidden size = T*M\\n    return (T*D) * (T*M) + (T*M) * O\\n\\ndef rnn_params(T, D, M, O):\\n    # Shared through time\\n    return (M*D) + (M*M) + (O*M)\\n\\nT, D, M, O = 100, 10, 15, 1\\np_ann = ann_params_flat(T, D, M, O)\\np_rnn = rnn_params(T, D, M, O)\\n\\nprint(\\"Flattened ANN params:\\", p_ann)\\nprint(\\"RNN params:\\", p_rnn)\\nprint(\\"ANN / RNN ratio:\\", p_ann / p_rnn)\\n\\n# Quick bar plot\\nlabels = [\\"Flattened ANN\\", \\"RNN (shared weights)\\"]\\nvalues = [p_ann, p_rnn]\\n\\nplt.figure()\\nplt.bar(labels, values)\\nplt.yscale(\\"log\\")  # so both bars are visible\\nplt.title(\\"Parameter count comparison (log scale)\\")\\nplt.ylabel(\\"Number of parameters\\")\\nplt.show()</code></pre>\\n\\n    <p>\\n      In this setup, you\u2019ll see a huge ratio (thousands of times more parameters for the flattened ANN),\\n      matching the intuition from the transcript.\\n    </p>\\n\\n    <h2 id=\\"7-coding-it-in-pytorch-manual-loop-to-really-see-weight-sharing\\">7) Coding it in PyTorch: manual loop (to really see weight sharing)</h2>\\n    <p>\\n      The fastest way to \u201cget\u201d RNNs is to implement the loop yourself once.\\n      Below is a minimal RNN cell you can train like any other module.\\n    </p>\\n\\n    <pre><code class=\\"language-python\\">import torch\\nimport torch.nn as nn\\nimport torch.nn.functional as F\\n\\nclass TinyElmanRNN(nn.Module):\\n    \\"\\"\\"\\n    Vanilla RNN (Elman unit) implemented explicitly:\\n      h_t = tanh(W_xh x_t + W_hh h_{t-1} + b_h)\\n      y_t = W_ho h_t + b_o\\n    \\"\\"\\"\\n    def __init__(self, input_size: int, hidden_size: int, output_size: int):\\n        super().__init__()\\n        self.input_size = input_size\\n        self.hidden_size = hidden_size\\n        self.output_size = output_size\\n\\n        # These are the ONLY learned weights, reused for every t\\n        self.W_xh = nn.Linear(input_size, hidden_size, bias=True)\\n        self.W_hh = nn.Linear(hidden_size, hidden_size, bias=False)\\n        self.W_ho = nn.Linear(hidden_size, output_size, bias=True)\\n\\n    def forward(self, x: torch.Tensor, h0: torch.Tensor | None = None):\\n        \\"\\"\\"\\n        x: (batch, T, D)  using batch_first layout here\\n        h0: (batch, M) or None\\n        Returns:\\n          y_all: (batch, T, O)  (pred at every step)\\n          h_last: (batch, M)\\n        \\"\\"\\"\\n        B, T, D = x.shape\\n        if h0 is None:\\n            h = torch.zeros(B, self.hidden_size, device=x.device, dtype=x.dtype)\\n        else:\\n            h = h0\\n\\n        y_steps = []\\n        for t in range(T):\\n            xt = x[:, t, :]  # (batch, D)\\n            h = torch.tanh(self.W_xh(xt) + self.W_hh(h))\\n            yt = self.W_ho(h)  # (batch, O)\\n            y_steps.append(yt)\\n\\n        y_all = torch.stack(y_steps, dim=1)  # (batch, T, O)\\n        return y_all, h\\n\\n# Example usage:\\nB, T, D = 32, 100, 10\\nM, O = 15, 1\\nmodel = TinyElmanRNN(D, M, O)\\n\\nx = torch.randn(B, T, D)\\ny_all, h_last = model(x)\\n\\n# Many-to-one binary classification: use only last step\\nlogits = y_all[:, -1, :]         # (B, 1)\\nprobs  = torch.sigmoid(logits)   # if binary classification</code></pre>\\n\\n    <div class=\\"callout\\">\\n      Notice how <code>self.W_xh</code> and <code>self.W_hh</code> are created <em>once</em> in <code>__init__</code>,\\n      then used repeatedly inside the time loop. That\u2019s the \u201csingle unit reused\u201d idea in code.\\n    </div>\\n\\n    <h2 id=\\"8-using-pytorch-s-built-in-nn-rnn-recommended-for-real-projects\\">8) Using PyTorch\u2019s built-in <span class=\\"kbd\\">nn.RNN</span> (recommended for real projects)</h2>\\n    <p>\\n      PyTorch provides <code>torch.nn.RNN</code> which handles the looping internally and exposes standardized weights\\n      (e.g., <code>weight_ih_l0</code>, <code>weight_hh_l0</code>) and batch/sequence layouts. \\n    </p>\\n\\n    <pre><code class=\\"language-python\\">import torch\\nimport torch.nn as nn\\n\\nD, M = 10, 15   # input_size, hidden_size\\nrnn = nn.RNN(\\n    input_size=D,\\n    hidden_size=M,\\n    num_layers=1,\\n    nonlinearity=\\"tanh\\",\\n    batch_first=True,  # input is (batch, T, D)\\n)\\n\\nB, T = 32, 100\\nx = torch.randn(B, T, D)\\n\\n# output: (B, T, M)   h_n: (num_layers, B, M)\\nout, h_n = rnn(x)\\n\\n# Many-to-one classifier head\\nhead = nn.Linear(M, 1)\\nlogits = head(out[:, -1, :])</code></pre>\\n\\n    <p>\\n      If you\u2019re ever unsure about shapes, inputs/outputs, or the exact meaning of those weight tensors,\\n      the official docs are the source of truth. \\n    </p>\\n\\n    <div class=\\"callout\\">\\n      <strong>Why the next section exists:</strong> <code>nn.RNN</code> gives you a clean implementation of the vanilla\\n      recurrence, but it does not change the recurrence itself. There is still only one hidden vector, and every new token\\n      can overwrite it. That is enough for short dependencies and for learning the idea, but it is too blunt when the model\\n      must remember something for many steps while also reacting to new input.\\n    </div>\\n\\n    <div class=\\"hr\\"></div>\\n\\n    <h2 id=\\"9-why-vanilla-rnn-memory-breaks-overwriting-and-gradient-chains\\">9) Why vanilla RNN memory breaks: overwriting and gradient chains</h2>\\n    <p>\\n      A vanilla RNN has only one state vector \\\\(h_t\\\\). Every step computes a new state from the current input and the previous\\n      state:\\n    </p>\\n    <div class=\\"eq\\">\\n      \\\\[\\n        h_t = \\\\tanh(W_{xh}x_t + W_{hh}h_{t-1} + b_h)\\n      \\\\]\\n    </div>\\n    <p>\\n      That compact formula is elegant, but it gives the model no explicit mechanism for deciding <em>how much old information\\n      to keep</em> and <em>how much new information to write</em>. The new candidate state can overwrite the old state too\\n      aggressively. During backpropagation through time, gradients also repeatedly multiply through recurrent transformations.\\n      Those products can shrink toward zero (<strong>vanishing gradients</strong>) or grow too large\\n      (<strong>exploding gradients</strong>).\\n    </p>\\n    <div class=\\"callout\\">\\n      <strong>The missing idea:</strong> a good sequence model needs a learnable way to say \u201ckeep this memory\u201d, \u201cforget this part\u201d,\\n      \u201cwrite this new information\u201d, and sometimes \u201chide this internal memory from the output\u201d.\\n    </div>\\n\\n    <figure>\\n      <svg class=\\"viz\\" viewBox=\\"0 0 980 300\\" role=\\"img\\" aria-label=\\"Vanilla RNN memory overwrite and gradient chain\\">\\n        <defs>\\n          <marker id=\\"rnn-failure-arrow\\" markerWidth=\\"10\\" markerHeight=\\"10\\" refX=\\"8\\" refY=\\"3\\" orient=\\"auto\\">\\n            <path d=\\"M0,0 L8,3 L0,6 Z\\" fill=\\"#0969da\\"></path>\\n          </marker>\\n        </defs>\\n        <text x=\\"30\\" y=\\"34\\" class=\\"title\\">Why vanilla recurrence runs out of control</text>\\n        <text x=\\"30\\" y=\\"60\\" class=\\"muted\\">One hidden vector must both store old facts and absorb every new token.</text>\\n\\n        <g transform=\\"translate(55,112)\\">\\n          <rect x=\\"0\\" y=\\"38\\" width=\\"106\\" height=\\"52\\" rx=\\"11\\" fill=\\"#eaf3ff\\" stroke=\\"#0969da\\"></rect>\\n          <rect x=\\"162\\" y=\\"38\\" width=\\"106\\" height=\\"52\\" rx=\\"11\\" fill=\\"#eaf3ff\\" stroke=\\"#0969da\\"></rect>\\n          <rect x=\\"324\\" y=\\"38\\" width=\\"106\\" height=\\"52\\" rx=\\"11\\" fill=\\"#eaf3ff\\" stroke=\\"#0969da\\"></rect>\\n          <rect x=\\"486\\" y=\\"38\\" width=\\"106\\" height=\\"52\\" rx=\\"11\\" fill=\\"#eaf3ff\\" stroke=\\"#0969da\\"></rect>\\n          <path fill=\\"none\\" d=\\"M106 64 L162 64 M268 64 L324 64 M430 64 L486 64\\" stroke=\\"#0969da\\" stroke-width=\\"2.3\\" marker-end=\\"url(#rnn-failure-arrow)\\"></path>\\n          <text x=\\"53\\" y=\\"70\\" class=\\"label\\" text-anchor=\\"middle\\">h1</text>\\n          <text x=\\"215\\" y=\\"70\\" class=\\"label\\" text-anchor=\\"middle\\">h2</text>\\n          <text x=\\"377\\" y=\\"70\\" class=\\"label\\" text-anchor=\\"middle\\">...</text>\\n          <text x=\\"539\\" y=\\"70\\" class=\\"label\\" text-anchor=\\"middle\\">hT</text>\\n          <rect x=\\"92\\" y=\\"132\\" width=\\"410\\" height=\\"40\\" rx=\\"10\\" fill=\\"#fff8e6\\" stroke=\\"#bf8700\\"></rect>\\n          <text x=\\"297\\" y=\\"157\\" class=\\"label\\" text-anchor=\\"middle\\">old information must survive every rewrite</text>\\n          <path d=\\"M52 38 C85 0 205 0 240 38\\" stroke=\\"#bf8700\\" stroke-width=\\"2.1\\" fill=\\"none\\"></path>\\n          <path d=\\"M215 90 C260 132 385 132 430 90\\" stroke=\\"#bf8700\\" stroke-width=\\"2.1\\" fill=\\"none\\"></path>\\n        </g>\\n\\n        <g transform=\\"translate(690,106)\\">\\n          <rect x=\\"0\\" y=\\"0\\" width=\\"216\\" height=\\"178\\" rx=\\"16\\" fill=\\"#f5f0ff\\" stroke=\\"#8250df\\" stroke-width=\\"1.5\\"></rect>\\n          <text x=\\"108\\" y=\\"36\\" class=\\"label\\" text-anchor=\\"middle\\">training signal</text>\\n          <path fill=\\"none\\" d=\\"M108 60 L108 130\\" stroke=\\"#8250df\\" stroke-width=\\"7\\" opacity=\\".25\\"></path>\\n          <path fill=\\"none\\" d=\\"M108 60 L108 100\\" stroke=\\"#8250df\\" stroke-width=\\"5\\" opacity=\\".45\\"></path>\\n          <path fill=\\"none\\" d=\\"M108 60 L108 78\\" stroke=\\"#8250df\\" stroke-width=\\"3\\" opacity=\\".75\\"></path>\\n          <text x=\\"108\\" y=\\"154\\" class=\\"muted\\" text-anchor=\\"middle\\">long products can vanish</text>\\n        </g>\\n      </svg>\\n      <figcaption>\\n        Gates are introduced because vanilla recurrence has no explicit keep/write control and because long recurrent chains are hard to train.\\n      </figcaption>\\n    </figure>\\n\\n    <h2 id=\\"10-gates-learnable-valves-for-memory\\">10) Gates: learnable valves for memory</h2>\\n    <p>\\n      The next improvement is not \u201cmake the hidden state bigger\u201d as the first move. A larger state can store more numbers,\\n      but it still gives the model no explicit instruction for <em>which</em> numbers should be preserved, overwritten,\\n      or exposed. GRUs and LSTMs solve that problem by adding <strong>gates</strong>. A gate is usually a sigmoid output:\\n    </p>\\n    <div class=\\"eq\\">\\n      \\\\[\\n        \\\\sigma(a) \\\\in (0,1)\\n      \\\\]\\n    </div>\\n    <p>\\n      Because a gate is between 0 and 1, it behaves like a soft valve:\\n    </p>\\n    <ul>\\n      <li>A value near 0 means \u201cblock this signal\u201d.</li>\\n      <li>A value near 1 means \u201clet this signal pass\u201d.</li>\\n      <li>Intermediate values blend old and new information.</li>\\n    </ul>\\n\\n    <p>\\n      The progression is:\\n    </p>\\n    <table>\\n      <thead>\\n        <tr>\\n          <th>Model</th>\\n          <th>Problem it fixes</th>\\n          <th>Remaining pressure that leads to the next idea</th>\\n        </tr>\\n      </thead>\\n      <tbody>\\n        <tr>\\n          <td>Vanilla RNN</td>\\n          <td>Introduces hidden state and weight sharing through time.</td>\\n          <td>The hidden state is overwritten by a single update rule, and long gradients are fragile.</td>\\n        </tr>\\n        <tr>\\n          <td>GRU</td>\\n          <td>Adds reset/update gates so the model can keep old state or write new state selectively.</td>\\n          <td>There is still one vector doing two jobs: long-term memory and exposed hidden representation.</td>\\n        </tr>\\n        <tr>\\n          <td>LSTM</td>\\n          <td>Separates protected cell memory \\\\(c_t\\\\) from exposed hidden state \\\\(h_t\\\\).</td>\\n          <td>The computation is still sequential, and seq2seq still pressures memory into recurrent states.</td>\\n        </tr>\\n        <tr>\\n          <td>Attention</td>\\n          <td>Lets the decoder look up relevant states directly instead of relying only on what survived in memory.</td>\\n          <td>The Transformer generalizes lookup so all tokens can read context directly and train in parallel.</td>\\n        </tr>\\n      </tbody>\\n    </table>\\n\\n    <figure>\\n      <svg class=\\"viz\\" viewBox=\\"0 0 980 390\\" role=\\"img\\" aria-label=\\"Vanilla RNN GRU and LSTM memory comparison\\">\\n        <defs>\\n          <marker id=\\"gate-arrow-blue\\" markerWidth=\\"10\\" markerHeight=\\"10\\" refX=\\"8\\" refY=\\"3\\" orient=\\"auto\\">\\n            <path d=\\"M0,0 L8,3 L0,6 Z\\" fill=\\"#0969da\\"></path>\\n          </marker>\\n          <marker id=\\"gate-arrow-purple\\" markerWidth=\\"10\\" markerHeight=\\"10\\" refX=\\"8\\" refY=\\"3\\" orient=\\"auto\\">\\n            <path d=\\"M0,0 L8,3 L0,6 Z\\" fill=\\"#8250df\\"></path>\\n          </marker>\\n        </defs>\\n        <text x=\\"30\\" y=\\"34\\" class=\\"title\\">How recurrent memory becomes more controllable</text>\\n        <text x=\\"30\\" y=\\"60\\" class=\\"muted\\">Vanilla RNN overwrites one hidden state. GRU adds update/reset gates. LSTM separates long-term cell memory from exposed hidden state.</text>\\n\\n        <g transform=\\"translate(48,112)\\">\\n          <rect x=\\"0\\" y=\\"0\\" width=\\"250\\" height=\\"205\\" rx=\\"16\\" fill=\\"#eaf3ff\\" stroke=\\"#0969da\\" stroke-width=\\"1.6\\"></rect>\\n          <text x=\\"125\\" y=\\"32\\" class=\\"label\\" text-anchor=\\"middle\\">Vanilla RNN</text>\\n          <text x=\\"125\\" y=\\"58\\" class=\\"muted\\" text-anchor=\\"middle\\">one hidden state</text>\\n          <rect x=\\"42\\" y=\\"82\\" width=\\"166\\" height=\\"52\\" rx=\\"12\\" fill=\\"#ffffff\\" stroke=\\"#0969da\\"></rect>\\n          <text x=\\"125\\" y=\\"114\\" class=\\"label\\" text-anchor=\\"middle\\">h_t = tanh(...)</text>\\n          <path fill=\\"none\\" d=\\"M24 108 L42 108\\" stroke=\\"#0969da\\" stroke-width=\\"2.2\\" marker-end=\\"url(#gate-arrow-blue)\\"></path>\\n          <path fill=\\"none\\" d=\\"M208 108 L230 108\\" stroke=\\"#0969da\\" stroke-width=\\"2.2\\" marker-end=\\"url(#gate-arrow-blue)\\"></path>\\n          <text x=\\"125\\" y=\\"166\\" class=\\"muted\\" text-anchor=\\"middle\\">simple, but old memory</text>\\n          <text x=\\"125\\" y=\\"186\\" class=\\"muted\\" text-anchor=\\"middle\\">is easy to overwrite</text>\\n        </g>\\n\\n        <g transform=\\"translate(365,112)\\">\\n          <rect x=\\"0\\" y=\\"0\\" width=\\"250\\" height=\\"205\\" rx=\\"16\\" fill=\\"#f3f8f1\\" stroke=\\"#1a7f37\\" stroke-width=\\"1.6\\"></rect>\\n          <text x=\\"125\\" y=\\"32\\" class=\\"label\\" text-anchor=\\"middle\\">GRU</text>\\n          <text x=\\"125\\" y=\\"58\\" class=\\"muted\\" text-anchor=\\"middle\\">hidden state + gates</text>\\n          <rect x=\\"32\\" y=\\"82\\" width=\\"82\\" height=\\"48\\" rx=\\"12\\" fill=\\"#ffffff\\" stroke=\\"#1a7f37\\"></rect>\\n          <rect x=\\"136\\" y=\\"82\\" width=\\"82\\" height=\\"48\\" rx=\\"12\\" fill=\\"#ffffff\\" stroke=\\"#1a7f37\\"></rect>\\n          <text x=\\"73\\" y=\\"112\\" class=\\"label\\" text-anchor=\\"middle\\">reset</text>\\n          <text x=\\"177\\" y=\\"112\\" class=\\"label\\" text-anchor=\\"middle\\">update</text>\\n          <path fill=\\"none\\" d=\\"M24 106 L32 106\\" stroke=\\"#1a7f37\\" stroke-width=\\"2.2\\" marker-end=\\"url(#gate-arrow-blue)\\"></path>\\n          <path fill=\\"none\\" d=\\"M218 106 L230 106\\" stroke=\\"#1a7f37\\" stroke-width=\\"2.2\\" marker-end=\\"url(#gate-arrow-blue)\\"></path>\\n          <text x=\\"125\\" y=\\"166\\" class=\\"muted\\" text-anchor=\\"middle\\">learns how much to keep</text>\\n          <text x=\\"125\\" y=\\"186\\" class=\\"muted\\" text-anchor=\\"middle\\">and how much to rewrite</text>\\n        </g>\\n\\n        <g transform=\\"translate(682,112)\\">\\n          <rect x=\\"0\\" y=\\"0\\" width=\\"250\\" height=\\"205\\" rx=\\"16\\" fill=\\"#f5f0ff\\" stroke=\\"#8250df\\" stroke-width=\\"1.6\\"></rect>\\n          <text x=\\"125\\" y=\\"32\\" class=\\"label\\" text-anchor=\\"middle\\">LSTM</text>\\n          <text x=\\"125\\" y=\\"58\\" class=\\"muted\\" text-anchor=\\"middle\\">cell state + hidden state</text>\\n          <rect x=\\"24\\" y=\\"82\\" width=\\"58\\" height=\\"46\\" rx=\\"10\\" fill=\\"#ffffff\\" stroke=\\"#8250df\\"></rect>\\n          <rect x=\\"96\\" y=\\"82\\" width=\\"58\\" height=\\"46\\" rx=\\"10\\" fill=\\"#ffffff\\" stroke=\\"#8250df\\"></rect>\\n          <rect x=\\"168\\" y=\\"82\\" width=\\"58\\" height=\\"46\\" rx=\\"10\\" fill=\\"#ffffff\\" stroke=\\"#8250df\\"></rect>\\n          <text x=\\"53\\" y=\\"111\\" class=\\"label\\" text-anchor=\\"middle\\">forget</text>\\n          <text x=\\"125\\" y=\\"111\\" class=\\"label\\" text-anchor=\\"middle\\">write</text>\\n          <text x=\\"197\\" y=\\"111\\" class=\\"label\\" text-anchor=\\"middle\\">output</text>\\n          <path fill=\\"none\\" d=\\"M24 150 L226 150\\" stroke=\\"#8250df\\" stroke-width=\\"2.4\\" marker-end=\\"url(#gate-arrow-purple)\\"></path>\\n          <text x=\\"125\\" y=\\"171\\" class=\\"muted\\" text-anchor=\\"middle\\">separate long-term cell path</text>\\n          <text x=\\"125\\" y=\\"190\\" class=\\"muted\\" text-anchor=\\"middle\\">helps memory persist</text>\\n        </g>\\n      </svg>\\n      <figcaption>\\n        GRU and LSTM do not change the basic sequence loop. They change the cell used inside the loop so memory is easier to preserve.\\n      </figcaption>\\n    </figure>\\n\\n    <p class=\\"muted\\">\\n      Historical note: LSTM was introduced before GRU. This chapter teaches GRU first because it is the simpler gated cell\\n      to understand, then LSTM as the more explicit long-term-memory design.\\n    </p>\\n\\n    <h2 id=\\"11-gru-the-simpler-gated-memory-cell\\">11) GRU: the simpler gated memory cell</h2>\\n    <p>\\n      A <strong>Gated Recurrent Unit</strong> is the smallest useful step beyond the vanilla RNN. It keeps one state,\\n      \\\\(h_t\\\\), like a vanilla RNN, but adds two gates:\\n    </p>\\n    <ul>\\n      <li><strong>Reset gate \\\\(r_t\\\\):</strong> controls how much of the previous state is used when computing the new candidate.</li>\\n      <li><strong>Update gate \\\\(z_t\\\\):</strong> controls how much old state is kept versus how much candidate state is written.</li>\\n    </ul>\\n    <p>\\n      One common convention, matching PyTorch\u2019s documentation, is:\\n    </p>\\n    <div class=\\"eq\\">\\n      \\\\[\\n        r_t = \\\\sigma(W_{ir}x_t + b_{ir} + W_{hr}h_{t-1} + b_{hr})\\n      \\\\]\\n      \\\\[\\n        z_t = \\\\sigma(W_{iz}x_t + b_{iz} + W_{hz}h_{t-1} + b_{hz})\\n      \\\\]\\n      \\\\[\\n        n_t = \\\\tanh(W_{in}x_t + b_{in} + r_t \\\\odot (W_{hn}h_{t-1} + b_{hn}))\\n      \\\\]\\n      \\\\[\\n        h_t = (1 - z_t) \\\\odot n_t + z_t \\\\odot h_{t-1}\\n      \\\\]\\n    </div>\\n    <p>\\n      With this convention, if \\\\(z_t\\\\) is close to 1, the GRU mostly keeps the old state. If \\\\(z_t\\\\) is close to 0,\\n      it mostly writes the candidate \\\\(n_t\\\\). That \u201ckeep vs update\u201d interpolation is the key mental model.\\n    </p>\\n\\n    <div class=\\"callout green\\">\\n      <strong>GRU mental model:</strong> \u201cI have one memory vector. At each step I learn whether to keep it, partially reset it,\\n      or overwrite parts of it with the new candidate.\u201d\\n    </div>\\n\\n    <p>\\n      This directly addresses the first failure mode of a vanilla RNN: accidental overwrite. If the model sees an important\\n      token early in a sequence, the update gate can keep that memory alive while less important later tokens only adjust\\n      part of the state. The reset gate gives the model a second useful behavior: when the current input starts a new local\\n      pattern, it can temporarily ignore older state while computing the candidate update.\\n    </p>\\n\\n    <figure>\\n      <svg class=\\"viz\\" viewBox=\\"0 0 980 310\\" role=\\"img\\" aria-label=\\"GRU reset and update gate equation flow\\">\\n        <defs>\\n          <marker id=\\"gru-flow-arrow\\" markerWidth=\\"10\\" markerHeight=\\"10\\" refX=\\"8\\" refY=\\"3\\" orient=\\"auto\\">\\n            <path d=\\"M0,0 L8,3 L0,6 Z\\" fill=\\"#0969da\\"></path>\\n          </marker>\\n        </defs>\\n        <text x=\\"30\\" y=\\"34\\" class=\\"title\\">GRU: one memory vector with controlled overwrite</text>\\n        <text x=\\"30\\" y=\\"60\\" class=\\"muted\\">The reset gate controls candidate construction; the update gate blends old memory with the candidate.</text>\\n\\n        <rect x=\\"58\\" y=\\"130\\" width=\\"140\\" height=\\"58\\" rx=\\"12\\" fill=\\"#eaf3ff\\" stroke=\\"#0969da\\"></rect>\\n        <text x=\\"128\\" y=\\"164\\" class=\\"label\\" text-anchor=\\"middle\\">old state h_{t-1}</text>\\n        <rect x=\\"58\\" y=\\"218\\" width=\\"140\\" height=\\"46\\" rx=\\"10\\" fill=\\"#f6f8fa\\" stroke=\\"#d0d7de\\"></rect>\\n        <text x=\\"128\\" y=\\"247\\" class=\\"label\\" text-anchor=\\"middle\\">input x_t</text>\\n\\n        <rect x=\\"286\\" y=\\"100\\" width=\\"150\\" height=\\"54\\" rx=\\"12\\" fill=\\"#fff8e6\\" stroke=\\"#bf8700\\"></rect>\\n        <text x=\\"361\\" y=\\"133\\" class=\\"label\\" text-anchor=\\"middle\\">reset gate r_t</text>\\n        <rect x=\\"286\\" y=\\"190\\" width=\\"150\\" height=\\"54\\" rx=\\"12\\" fill=\\"#fff8e6\\" stroke=\\"#bf8700\\"></rect>\\n        <text x=\\"361\\" y=\\"223\\" class=\\"label\\" text-anchor=\\"middle\\">update gate z_t</text>\\n\\n        <rect x=\\"528\\" y=\\"116\\" width=\\"160\\" height=\\"64\\" rx=\\"13\\" fill=\\"#f3f8f1\\" stroke=\\"#1a7f37\\"></rect>\\n        <text x=\\"608\\" y=\\"142\\" class=\\"label\\" text-anchor=\\"middle\\">candidate</text>\\n        <text x=\\"608\\" y=\\"164\\" class=\\"label\\" text-anchor=\\"middle\\">memory n_t</text>\\n\\n        <rect x=\\"760\\" y=\\"144\\" width=\\"154\\" height=\\"70\\" rx=\\"14\\" fill=\\"#f5f0ff\\" stroke=\\"#8250df\\"></rect>\\n        <text x=\\"837\\" y=\\"174\\" class=\\"label\\" text-anchor=\\"middle\\">new state</text>\\n        <text x=\\"837\\" y=\\"196\\" class=\\"label\\" text-anchor=\\"middle\\">h_t</text>\\n\\n        <path fill=\\"none\\" d=\\"M198 150 L286 126\\" stroke=\\"#0969da\\" stroke-width=\\"2.2\\" marker-end=\\"url(#gru-flow-arrow)\\"></path>\\n        <path fill=\\"none\\" d=\\"M198 158 L528 148\\" stroke=\\"#0969da\\" stroke-width=\\"2.2\\" marker-end=\\"url(#gru-flow-arrow)\\"></path>\\n        <path fill=\\"none\\" d=\\"M198 241 L286 217\\" stroke=\\"#0969da\\" stroke-width=\\"2.2\\" marker-end=\\"url(#gru-flow-arrow)\\"></path>\\n        <path fill=\\"none\\" d=\\"M436 127 L528 142\\" stroke=\\"#bf8700\\" stroke-width=\\"2.2\\" marker-end=\\"url(#gru-flow-arrow)\\"></path>\\n        <path fill=\\"none\\" d=\\"M688 148 L760 172\\" stroke=\\"#1a7f37\\" stroke-width=\\"2.4\\" marker-end=\\"url(#gru-flow-arrow)\\"></path>\\n        <path fill=\\"none\\" d=\\"M436 217 L760 190\\" stroke=\\"#bf8700\\" stroke-width=\\"2.2\\" marker-end=\\"url(#gru-flow-arrow)\\"></path>\\n        <path d=\\"M128 130 C210 72 675 72 815 144\\" stroke=\\"#8250df\\" stroke-width=\\"2.2\\" fill=\\"none\\" marker-end=\\"url(#gru-flow-arrow)\\"></path>\\n        <text x=\\"548\\" y=\\"82\\" class=\\"muted\\" text-anchor=\\"middle\\">h_t = (1-z_t) * n_t + z_t * h_{t-1}</text>\\n      </svg>\\n      <figcaption>\\n        A GRU still has one memory vector, but the update gate makes the final state an explicit blend of old memory and candidate memory.\\n      </figcaption>\\n    </figure>\\n\\n    <pre><code class=\\"language-python\\">import torch\\nimport torch.nn as nn\\n\\nB, T, D = 32, 100, 10     # batch, sequence length, input features\\nH = 64                    # hidden size\\n\\ngru = nn.GRU(\\n    input_size=D,\\n    hidden_size=H,\\n    num_layers=1,\\n    batch_first=True,\\n)\\n\\nx = torch.randn(B, T, D)\\nout, h_n = gru(x)\\n\\nprint(out.shape)  # (B, T, H): hidden state at every time step\\nprint(h_n.shape)  # (1, B, H): final hidden state for the last layer\\n\\n# Many-to-one classifier: use the final time-step representation\\nhead = nn.Linear(H, 1)\\nlogits = head(out[:, -1, :])</code></pre>\\n\\n    <div class=\\"callout orange\\">\\n      <strong>Why move from GRU to LSTM?</strong> A GRU is compact and often very strong, but its single state vector still has\\n      to be both the long-term memory and the visible representation passed onward. If you want a more explicit design where\\n      long-term memory can be preserved while only part of it is exposed at the current step, you need a separate memory path.\\n      That is the reason for the LSTM cell state.\\n    </div>\\n\\n    <h2 id=\\"12-lstm-separate-long-term-memory-from-exposed-hidden-state\\">12) LSTM: separate long-term memory from exposed hidden state</h2>\\n    <p>\\n      A <strong>Long Short-Term Memory</strong> cell takes the gating idea further by adding a separate <strong>cell state</strong>,\\n      \\\\(c_t\\\\), alongside the hidden state, \\\\(h_t\\\\). The cell state is the long-term memory path. The hidden state is the exposed\\n      representation used for outputs and for the next recurrent computation.\\n    </p>\\n    <p>\\n      LSTMs use three main gates plus a candidate update:\\n    </p>\\n    <ul>\\n      <li><strong>Forget gate \\\\(f_t\\\\):</strong> how much old cell memory \\\\(c_{t-1}\\\\) to keep.</li>\\n      <li><strong>Input/write gate \\\\(i_t\\\\):</strong> how much new candidate information to write.</li>\\n      <li><strong>Candidate \\\\(g_t\\\\):</strong> proposed new content for the cell memory.</li>\\n      <li><strong>Output gate \\\\(o_t\\\\):</strong> how much cell memory to expose as hidden state \\\\(h_t\\\\).</li>\\n    </ul>\\n    <div class=\\"eq\\">\\n      \\\\[\\n        f_t = \\\\sigma(W_{if}x_t + b_{if} + W_{hf}h_{t-1} + b_{hf})\\n      \\\\]\\n      \\\\[\\n        i_t = \\\\sigma(W_{ii}x_t + b_{ii} + W_{hi}h_{t-1} + b_{hi})\\n      \\\\]\\n      \\\\[\\n        g_t = \\\\tanh(W_{ig}x_t + b_{ig} + W_{hg}h_{t-1} + b_{hg})\\n      \\\\]\\n      \\\\[\\n        o_t = \\\\sigma(W_{io}x_t + b_{io} + W_{ho}h_{t-1} + b_{ho})\\n      \\\\]\\n      \\\\[\\n        c_t = f_t \\\\odot c_{t-1} + i_t \\\\odot g_t\\n      \\\\]\\n      \\\\[\\n        h_t = o_t \\\\odot \\\\tanh(c_t)\\n      \\\\]\\n    </div>\\n\\n    <div class=\\"callout blue\\">\\n      <strong>LSTM mental model:</strong> \u201cI keep a protected long-term notebook \\\\(c_t\\\\), decide what to erase, decide what\\n      to write, and decide how much of the notebook to show as \\\\(h_t\\\\).\u201d\\n    </div>\\n\\n    <figure>\\n      <svg class=\\"viz\\" viewBox=\\"0 0 980 310\\" role=\\"img\\" aria-label=\\"LSTM cell state equation flow with forget input candidate and output gates\\">\\n        <defs>\\n          <marker id=\\"lstm-flow-arrow\\" markerWidth=\\"10\\" markerHeight=\\"10\\" refX=\\"8\\" refY=\\"3\\" orient=\\"auto\\">\\n            <path d=\\"M0,0 L8,3 L0,6 Z\\" fill=\\"#8250df\\"></path>\\n          </marker>\\n        </defs>\\n        <text x=\\"30\\" y=\\"34\\" class=\\"title\\">LSTM: protected cell memory plus exposed hidden state</text>\\n        <text x=\\"30\\" y=\\"60\\" class=\\"muted\\">The cell state carries long-term memory; gates decide what is erased, written, and revealed.</text>\\n\\n        <rect x=\\"72\\" y=\\"126\\" width=\\"140\\" height=\\"56\\" rx=\\"12\\" fill=\\"#eaf3ff\\" stroke=\\"#0969da\\"></rect>\\n        <text x=\\"142\\" y=\\"160\\" class=\\"label\\" text-anchor=\\"middle\\">c_{t-1}</text>\\n        <path d=\\"M212 154 L768 154\\" stroke=\\"#8250df\\" stroke-width=\\"5\\" fill=\\"none\\" marker-end=\\"url(#lstm-flow-arrow)\\"></path>\\n        <rect x=\\"768\\" y=\\"126\\" width=\\"140\\" height=\\"56\\" rx=\\"12\\" fill=\\"#f5f0ff\\" stroke=\\"#8250df\\"></rect>\\n        <text x=\\"838\\" y=\\"160\\" class=\\"label\\" text-anchor=\\"middle\\">c_t</text>\\n\\n        <rect x=\\"284\\" y=\\"96\\" width=\\"116\\" height=\\"48\\" rx=\\"11\\" fill=\\"#fff8e6\\" stroke=\\"#bf8700\\"></rect>\\n        <text x=\\"342\\" y=\\"126\\" class=\\"label\\" text-anchor=\\"middle\\">forget f_t</text>\\n        <rect x=\\"458\\" y=\\"96\\" width=\\"116\\" height=\\"48\\" rx=\\"11\\" fill=\\"#f3f8f1\\" stroke=\\"#1a7f37\\"></rect>\\n        <text x=\\"516\\" y=\\"126\\" class=\\"label\\" text-anchor=\\"middle\\">write i_t g_t</text>\\n        <rect x=\\"632\\" y=\\"210\\" width=\\"116\\" height=\\"48\\" rx=\\"11\\" fill=\\"#fff8e6\\" stroke=\\"#bf8700\\"></rect>\\n        <text x=\\"690\\" y=\\"240\\" class=\\"label\\" text-anchor=\\"middle\\">output o_t</text>\\n\\n        <rect x=\\"96\\" y=\\"218\\" width=\\"146\\" height=\\"44\\" rx=\\"10\\" fill=\\"#f6f8fa\\" stroke=\\"#d0d7de\\"></rect>\\n        <text x=\\"169\\" y=\\"246\\" class=\\"label\\" text-anchor=\\"middle\\">x_t, h_{t-1}</text>\\n        <path d=\\"M242 240 C300 198 306 164 342 144\\" stroke=\\"#0969da\\" stroke-width=\\"2.1\\" fill=\\"none\\" marker-end=\\"url(#lstm-flow-arrow)\\"></path>\\n        <path d=\\"M242 240 C390 198 470 166 516 144\\" stroke=\\"#0969da\\" stroke-width=\\"2.1\\" fill=\\"none\\" marker-end=\\"url(#lstm-flow-arrow)\\"></path>\\n        <path fill=\\"none\\" d=\\"M242 240 L632 234\\" stroke=\\"#0969da\\" stroke-width=\\"2.1\\" marker-end=\\"url(#lstm-flow-arrow)\\"></path>\\n\\n        <rect x=\\"782\\" y=\\"218\\" width=\\"126\\" height=\\"48\\" rx=\\"11\\" fill=\\"#f3f8f1\\" stroke=\\"#1a7f37\\"></rect>\\n        <text x=\\"845\\" y=\\"248\\" class=\\"label\\" text-anchor=\\"middle\\">h_t</text>\\n        <path fill=\\"none\\" d=\\"M838 182 L845 218\\" stroke=\\"#8250df\\" stroke-width=\\"2.4\\" marker-end=\\"url(#lstm-flow-arrow)\\"></path>\\n        <path fill=\\"none\\" d=\\"M748 234 L782 242\\" stroke=\\"#bf8700\\" stroke-width=\\"2.2\\" marker-end=\\"url(#lstm-flow-arrow)\\"></path>\\n        <text x=\\"490\\" y=\\"284\\" class=\\"muted\\" text-anchor=\\"middle\\">c_t = f_t * c_{t-1} + i_t * g_t,   h_t = o_t * tanh(c_t)</text>\\n      </svg>\\n      <figcaption>\\n        LSTM explicitly separates the protected cell-memory update from the exposed hidden-state output.\\n      </figcaption>\\n    </figure>\\n\\n    <pre><code class=\\"language-python\\">import torch\\nimport torch.nn as nn\\n\\nB, T, D = 32, 100, 10\\nH = 64\\n\\nlstm = nn.LSTM(\\n    input_size=D,\\n    hidden_size=H,\\n    num_layers=1,\\n    batch_first=True,\\n)\\n\\nx = torch.randn(B, T, D)\\nout, (h_n, c_n) = lstm(x)\\n\\nprint(out.shape)  # (B, T, H): hidden state at every time step\\nprint(h_n.shape)  # (1, B, H): final hidden state\\nprint(c_n.shape)  # (1, B, H): final cell state\\n\\nhead = nn.Linear(H, 1)\\nlogits = head(out[:, -1, :])</code></pre>\\n\\n    <p>\\n      Compared with a GRU, the LSTM is more explicit: one gate forgets old cell memory, one gate writes new cell memory, and\\n      one gate controls what part of the internal memory becomes visible as \\\\(h_t\\\\). That makes the design easier to reason\\n      about for long dependencies, but it also adds parameters and computation. In practice, GRU is often a good first gated\\n      baseline; LSTM is the stronger choice when you want the separate cell-memory path and can afford the extra complexity.\\n    </p>\\n\\n    <div class=\\"callout\\">\\n      <strong>Why LSTM still does not finish the story:</strong> LSTMs make recurrence better, but they are still recurrent.\\n      Step \\\\(t\\\\) still waits for step \\\\(t-1\\\\), and an encoder-decoder LSTM still tends to compress source information into\\n      recurrent states. The next idea is not another gate; it is a different memory interface: direct lookup over earlier\\n      token states.\\n    </div>\\n\\n    <h2 id=\\"13-gru-vs-lstm-vs-vanilla-rnn-when-to-use-which\\">13) GRU vs LSTM vs vanilla RNN: when to use which</h2>\\n    <p>\\n      The choice is therefore not a popularity contest. It follows the problem you are trying to solve. Use the simplest\\n      recurrent cell that carries enough memory for the task, then move to the next mechanism only when the limitation becomes\\n      the bottleneck.\\n    </p>\\n    <table>\\n      <thead>\\n        <tr>\\n          <th>Cell</th>\\n          <th>State carried through time</th>\\n          <th>Memory control</th>\\n          <th>Practical use</th>\\n        </tr>\\n      </thead>\\n      <tbody>\\n        <tr>\\n          <td>Vanilla RNN</td>\\n          <td>One hidden state \\\\(h_t\\\\)</td>\\n          <td>No explicit gates</td>\\n          <td>Best for teaching and very short dependencies; rarely the strongest production choice.</td>\\n        </tr>\\n        <tr>\\n          <td>GRU</td>\\n          <td>One hidden state \\\\(h_t\\\\)</td>\\n          <td>Reset and update gates</td>\\n          <td>Simpler than LSTM, fewer parameters, often a strong baseline for sequence classification/forecasting.</td>\\n        </tr>\\n        <tr>\\n          <td>LSTM</td>\\n          <td>Hidden state \\\\(h_t\\\\) plus cell state \\\\(c_t\\\\)</td>\\n          <td>Forget, input/write, candidate, output gates</td>\\n          <td>More explicit memory control; useful when long dependencies matter and recurrence is still appropriate.</td>\\n        </tr>\\n        <tr>\\n          <td>Attention/Transformer</td>\\n          <td>Token representations plus attention over context</td>\\n          <td>Content-based lookup instead of recurrent compression</td>\\n          <td>Dominant for LLMs because training parallelizes and each token can directly access relevant context.</td>\\n        </tr>\\n      </tbody>\\n    </table>\\n\\n    <h3 id=\\"bidirectional-recurrent-models\\">Bidirectional recurrent models</h3>\\n    <p>\\n      After gates, another natural question is direction: if the entire input sentence is already known, why should the model\\n      only read left-to-right? A bidirectional RNN/GRU/LSTM runs one recurrent model left-to-right and another right-to-left,\\n      then combines their representations. This is useful when the full input sequence is known, such as classification,\\n      tagging, or embedding a sentence. It is not valid for pure left-to-right generation, because a generator cannot use\\n      future tokens that have not been produced yet.\\n    </p>\\n\\n    <pre><code class=\\"language-python\\">import torch\\nimport torch.nn as nn\\n\\nB, T, D = 32, 100, 10\\nH = 64\\n\\nencoder = nn.LSTM(\\n    input_size=D,\\n    hidden_size=H,\\n    batch_first=True,\\n    bidirectional=True,\\n)\\n\\nx = torch.randn(B, T, D)\\nout, (h_n, c_n) = encoder(x)\\n\\nprint(out.shape)  # (B, T, 2*H): forward and backward states concatenated</code></pre>\\n\\n    <h2 id=\\"14-why-attention-still-mattered-after-gru-lstm\\">14) Why attention still mattered after GRU/LSTM</h2>\\n    <p>\\n      At this point the story has fixed three problems: weight sharing made sequence models compact, gates made memory\\n      controllable, and bidirectionality let encoders use both left and right context when the full input is known. But\\n      none of these changes remove the deepest recurrent limitation:\\n    </p>\\n    <ul>\\n      <li><strong>Sequential compute:</strong> step \\\\(t\\\\) depends on \\\\(t-1\\\\), so training cannot parallelize across time as easily as Transformers.</li>\\n      <li><strong>Compression pressure:</strong> encoder-decoder recurrence still tends to squeeze a whole source sequence through hidden states.</li>\\n      <li><strong>Long-context access:</strong> a decoder may need a specific old token directly, not just whatever survived in state.</li>\\n    </ul>\\n    <p>\\n      Attention keeps the useful idea of sequence-conditioned output, but changes the memory interface. Instead of asking one\\n      hidden state to carry everything, the decoder can look back at all encoder states. The Transformer then takes the next step:\\n      it uses self-attention so tokens can read other tokens directly.\\n    </p>\\n    <div class=\\"callout orange\\">\\n      <strong>Bridge to Transformers:</strong> GRU/LSTM make recurrent memory more controllable. Attention changes the shape of\\n      memory itself from \u201ccarry a state forward\u201d to \u201clook up the relevant token states when needed.\u201d\\n    </div>\\n\\n    <figure>\\n      <svg class=\\"viz\\" viewBox=\\"0 0 980 330\\" role=\\"img\\" aria-label=\\"Recurrent memory compared to attention lookup\\">\\n        <defs>\\n          <marker id=\\"rnn-bridge-arrow\\" markerWidth=\\"10\\" markerHeight=\\"10\\" refX=\\"8\\" refY=\\"3\\" orient=\\"auto\\">\\n            <path d=\\"M0,0 L8,3 L0,6 Z\\" fill=\\"#0969da\\"></path>\\n          </marker>\\n        </defs>\\n        <text x=\\"30\\" y=\\"34\\" class=\\"title\\">From carrying memory to looking up memory</text>\\n        <text x=\\"30\\" y=\\"60\\" class=\\"muted\\">Gates improve what survives in state; attention changes the interface so old states remain directly addressable.</text>\\n\\n        <g transform=\\"translate(58,110)\\">\\n          <text x=\\"180\\" y=\\"-18\\" class=\\"label\\" text-anchor=\\"middle\\">Recurrent memory</text>\\n          <rect x=\\"0\\" y=\\"34\\" width=\\"74\\" height=\\"44\\" rx=\\"9\\" fill=\\"#eaf3ff\\" stroke=\\"#0969da\\"></rect>\\n          <rect x=\\"102\\" y=\\"34\\" width=\\"74\\" height=\\"44\\" rx=\\"9\\" fill=\\"#eaf3ff\\" stroke=\\"#0969da\\"></rect>\\n          <rect x=\\"204\\" y=\\"34\\" width=\\"74\\" height=\\"44\\" rx=\\"9\\" fill=\\"#eaf3ff\\" stroke=\\"#0969da\\"></rect>\\n          <path fill=\\"none\\" d=\\"M74 56 L102 56 M176 56 L204 56\\" stroke=\\"#0969da\\" stroke-width=\\"2.3\\" marker-end=\\"url(#rnn-bridge-arrow)\\"></path>\\n          <rect x=\\"112\\" y=\\"126\\" width=\\"154\\" height=\\"52\\" rx=\\"12\\" fill=\\"#fff8e6\\" stroke=\\"#bf8700\\"></rect>\\n          <path fill=\\"none\\" d=\\"M241 78 L202 126\\" stroke=\\"#bf8700\\" stroke-width=\\"2.3\\" marker-end=\\"url(#rnn-bridge-arrow)\\"></path>\\n          <text x=\\"37\\" y=\\"62\\" class=\\"label\\" text-anchor=\\"middle\\">h1</text>\\n          <text x=\\"139\\" y=\\"62\\" class=\\"label\\" text-anchor=\\"middle\\">h2</text>\\n          <text x=\\"241\\" y=\\"62\\" class=\\"label\\" text-anchor=\\"middle\\">hT</text>\\n          <text x=\\"189\\" y=\\"157\\" class=\\"label\\" text-anchor=\\"middle\\">decoder gets summary</text>\\n        </g>\\n\\n        <g transform=\\"translate(525,110)\\">\\n          <text x=\\"190\\" y=\\"-18\\" class=\\"label\\" text-anchor=\\"middle\\">Attention lookup</text>\\n          <rect x=\\"0\\" y=\\"34\\" width=\\"74\\" height=\\"44\\" rx=\\"9\\" fill=\\"#eaf3ff\\" stroke=\\"#0969da\\"></rect>\\n          <rect x=\\"102\\" y=\\"34\\" width=\\"74\\" height=\\"44\\" rx=\\"9\\" fill=\\"#eaf3ff\\" stroke=\\"#0969da\\"></rect>\\n          <rect x=\\"204\\" y=\\"34\\" width=\\"74\\" height=\\"44\\" rx=\\"9\\" fill=\\"#eaf3ff\\" stroke=\\"#0969da\\"></rect>\\n          <rect x=\\"306\\" y=\\"34\\" width=\\"74\\" height=\\"44\\" rx=\\"9\\" fill=\\"#eaf3ff\\" stroke=\\"#0969da\\"></rect>\\n          <text x=\\"37\\" y=\\"62\\" class=\\"label\\" text-anchor=\\"middle\\">h1</text>\\n          <text x=\\"139\\" y=\\"62\\" class=\\"label\\" text-anchor=\\"middle\\">h2</text>\\n          <text x=\\"241\\" y=\\"62\\" class=\\"label\\" text-anchor=\\"middle\\">h3</text>\\n          <text x=\\"343\\" y=\\"62\\" class=\\"label\\" text-anchor=\\"middle\\">h4</text>\\n          <rect x=\\"102\\" y=\\"142\\" width=\\"176\\" height=\\"54\\" rx=\\"12\\" fill=\\"#f5f0ff\\" stroke=\\"#8250df\\"></rect>\\n          <text x=\\"190\\" y=\\"174\\" class=\\"label\\" text-anchor=\\"middle\\">decoder query</text>\\n          <path d=\\"M190 142 C126 112 72 100 37 78\\" stroke=\\"#8250df\\" stroke-width=\\"2.2\\" fill=\\"none\\" marker-end=\\"url(#rnn-bridge-arrow)\\"></path>\\n          <path d=\\"M190 142 C170 112 150 100 139 78\\" stroke=\\"#8250df\\" stroke-width=\\"2.2\\" fill=\\"none\\" marker-end=\\"url(#rnn-bridge-arrow)\\"></path>\\n          <path d=\\"M190 142 C222 112 234 100 241 78\\" stroke=\\"#8250df\\" stroke-width=\\"2.2\\" fill=\\"none\\" marker-end=\\"url(#rnn-bridge-arrow)\\"></path>\\n          <path d=\\"M190 142 C286 112 326 100 343 78\\" stroke=\\"#8250df\\" stroke-width=\\"2.8\\" fill=\\"none\\" marker-end=\\"url(#rnn-bridge-arrow)\\"></path>\\n          <text x=\\"190\\" y=\\"226\\" class=\\"muted\\" text-anchor=\\"middle\\">high weight can select the specific useful state</text>\\n        </g>\\n      </svg>\\n      <figcaption>\\n        Attention does not replace the idea of sequence-conditioned output; it replaces the memory interface from \u201ccarry everything forward\u201d to \u201clook up what is needed.\u201d\\n      </figcaption>\\n    </figure>\\n\\n    <h2 id=\\"15-quick-mental-model-recap\\">15) Quick mental model recap</h2>\\n    <ul>\\n      <li><strong>RNN = MLP cell + memory.</strong> The \u201cmemory\u201d is the hidden state \\\\(h_t\\\\).</li>\\n      <li><strong>One cell reused at every time step.</strong> Same weights, new data + updated state.</li>\\n      <li><strong>GRU = RNN + keep/reset gates.</strong> It has one hidden state but learns how much old state to preserve.</li>\\n      <li><strong>LSTM = RNN + protected cell state.</strong> It separates long-term cell memory \\\\(c_t\\\\) from exposed hidden state \\\\(h_t\\\\).</li>\\n      <li><strong>Outputs at every step are optional.</strong> Many tasks use only the last output; translation uses stepwise decoder outputs.</li>\\n      <li><strong>Cost savings come from sharing.</strong> Parameter count doesn\u2019t blow up with \\\\(T\\\\).</li>\\n      <li><strong>Padding is not meaning.</strong> Padding makes rectangular tensors; masks/lengths stop it from affecting learning.</li>\\n      <li><strong>Encoder-decoder RNNs are historical but important.</strong> They explain the vocabulary of hidden state, teacher forcing, autoregressive decoding, and attention.</li>\\n    </ul>\\n\\n    <div class=\\"callout\\">\\n      Next step: the Transformer chapter keeps tokens, embeddings, decoder outputs, and autoregressive generation. It first fixes\\n      the RNN encoder-decoder bottleneck with cross-attention, then generalizes the idea into self-attention and GPT-style\\n      causal generation.\\n    </div>\\n  </main>"}'),d={title:"Recurrent Neural Networks (RNNs) \u2014 Sequence Memory, GRU/LSTM, Translation, and Weight Sharing",slug:"/part5-deep-learning-and-llms/10-recurrent-neural-networks",description:"A practical, code-oriented tutorial on why RNNs exist, what goes in and comes out at each time step, how a basic Elman unit computes hidden state, how GRU/LSTM gates improve memory, and how recurrent weight sharing ke...",sidebar_label:"10. Recurrent neural networks",pagination_label:"10. Recurrent neural networks",hide_title:!0,hide_table_of_contents:!0},l=void 0,h={},c=[];function m(e){return(0,a.jsx)(o.A,{content:i})}function p(e={}){const{wrapper:t}={...(0,s.R)(),...e.components};return t?(0,a.jsx)(t,{...e,children:(0,a.jsx)(m,{...e})}):m()}}}]);